  insert into public.recipe_equipment (recipe_id, equipment_code)
insert into _new_steps (slug, position, instruction) values
  ('agneau-raisins-semoule', 1, 'Éplucher et émincer les oignons ; éplucher les carottes et les couper en rondelles épaisses d''environ 1 cm.'),
  ('agneau-raisins-semoule', 2, 'Chauffer l''huile dans une cocotte à feu vif. Dorer l''agneau en deux fois, 3 à 4 minutes par fournée, jusqu''à ce que les morceaux soient bien colorés sur toutes les faces.'),
  ('agneau-raisins-semoule', 3, 'Baisser à feu moyen, ajouter les oignons et faire revenir 5 minutes en remuant, jusqu''à ce qu''ils soient translucides. Ajouter la cannelle et le cumin, mélanger 1 minute.'),
  ('agneau-raisins-semoule', 4, 'Ajouter les carottes, l''eau et le cube émietté. Porter à ébullition, puis couvrir et laisser mijoter 1 h 15 à feu doux : la viande doit se défaire à la fourchette.'),
  ('agneau-raisins-semoule', 5, 'Ajouter les raisins secs et le miel, mélanger et poursuivre 15 minutes à découvert pour que la sauce épaississe légèrement.'),
  ('agneau-raisins-semoule', 6, 'Pendant ce temps, faire griller les amandes 3 à 4 minutes à sec dans une poêle à feu moyen, en remuant, jusqu''à ce qu''elles blondissent. Préparer la semoule : la couvrir du même volume d''eau bouillante, couvrir 5 minutes, puis l''égrener à la fourchette.'),
  ('agneau-raisins-semoule', 7, 'Servir l''agneau et sa sauce sur la semoule, parsemé d''amandes grillées.'),
  ('aubergines-parmesane', 1, 'Préchauffer le four à 200 °C. Couper les aubergines en tranches d''environ 1 cm, les poser sur la plaque du four et les badigeonner d''huile sur les deux faces.'),
  ('aubergines-parmesane', 2, 'Rôtir 20 minutes en les retournant à mi-cuisson, jusqu''à ce qu''elles soient tendres et dorées.'),
  ('aubergines-parmesane', 3, 'Pendant ce temps, écraser l''ail et le faire mijoter avec le coulis 10 minutes dans une casserole à feu doux ; saler. Couper la mozzarella en tranches.'),
  ('aubergines-parmesane', 4, 'Baisser le four à 190 °C. Dans un plat allant au four, alterner une couche de sauce, d''aubergines, de mozzarella et quelques feuilles de basilic ; recommencer et terminer par de la sauce.'),
  ('aubergines-parmesane', 5, 'Parsemer de parmesan et enfourner 20 minutes, jusqu''à ce que le dessus gratine et que la sauce bouillonne sur les bords. Laisser reposer 5 minutes avant de servir.'),
  ('blanquette-veau', 1, 'Mettre le veau dans un faitout, couvrir d''eau froide et porter à ébullition. Écumer la mousse grise qui remonte pendant 2 à 3 minutes.'),
  ('blanquette-veau', 2, 'Ajouter les cubes émiettés, l''oignon épluché coupé en deux, les carottes en tronçons et le laurier. Laisser cuire 1 h 30 à petit frémissement, à couvert : la viande doit être fondante.'),
  ('blanquette-veau', 3, 'Environ 20 minutes avant la fin, lancer le riz dans une casserole d''eau bouillante, 12 minutes environ. Couper les champignons en quartiers et les faire revenir 5 minutes dans une noix de beurre à feu moyen.'),
  ('blanquette-veau', 4, 'Égoutter la viande et les carottes en gardant le bouillon. Dans une casserole, faire fondre le reste du beurre à feu moyen, ajouter la farine et remuer 2 minutes sans laisser colorer.'),
  ('blanquette-veau', 5, 'Verser 60 cl de bouillon chaud petit à petit en fouettant, et laisser épaissir 5 minutes à feu doux jusqu''à ce que la sauce nappe la cuillère.'),
  ('blanquette-veau', 6, 'Hors du feu, ajouter la crème et le jus du citron, goûter, saler et poivrer. Remettre la viande, les carottes et les champignons et réchauffer 10 minutes à feu très doux, sans faire bouillir. Servir avec le riz.'),
  ('boeuf-bourguignon', 1, 'Éplucher et émincer les oignons ; peler l''ail ; couper les carottes en rondelles. Bien éponger la viande pour qu''elle dore au lieu de bouillir.'),
  ('boeuf-bourguignon', 2, 'Chauffer l''huile dans une cocotte à feu vif. Dorer la viande en trois fois, 4 minutes par fournée, sans trop remuer pour qu''elle colore bien. Réserver.'),
  ('boeuf-bourguignon', 3, 'Baisser à feu moyen, faire revenir les lardons et les oignons 5 minutes. Saupoudrer de farine et remuer 1 minute.'),
  ('boeuf-bourguignon', 4, 'Remettre la viande, verser le vin, puis ajouter l''ail, les carottes, le thym et le laurier. Compléter d''eau juste à hauteur de la viande si besoin, saler et poivrer.'),
  ('boeuf-bourguignon', 5, 'Porter à ébullition, puis couvrir et laisser mijoter 2 h 30 à feu très doux, en remuant de temps en temps : la sauce doit à peine frémir.'),
  ('boeuf-bourguignon', 6, 'Couper les champignons en quartiers et les faire dorer 5 minutes dans une poêle chaude. Les ajouter à la cocotte et cuire encore 30 minutes, jusqu''à ce que la viande se coupe à la cuillère.'),
  ('boeuf-brocoli-saute', 1, 'Mélanger les lanières de bœuf avec la fécule et la moitié de la sauce soja ; laisser reposer pendant la suite de la préparation.'),
  ('boeuf-brocoli-saute', 2, 'Cuire le riz dans une casserole d''eau bouillante 10 à 12 minutes, puis l''égoutter.'),
  ('boeuf-brocoli-saute', 3, 'Détailler le brocoli en petits bouquets et les plonger 2 minutes dans une casserole d''eau bouillante, puis les égoutter : ils doivent rester bien verts et croquants. Hacher l''ail, râper le gingembre.'),
  ('boeuf-brocoli-saute', 4, 'Chauffer l''huile de tournesol dans une poêle ou un wok à feu très vif. Saisir le bœuf 2 minutes en remuant, jusqu''à ce qu''il soit doré.'),
  ('boeuf-brocoli-saute', 5, 'Ajouter l''ail et le gingembre 30 secondes, puis le brocoli 2 minutes en remuant.'),
  ('boeuf-brocoli-saute', 6, 'Verser le reste de sauce soja et l''huile de sésame, mélanger 30 secondes et servir aussitôt avec le riz.'),
  ('bolognaise', 1, 'Éplucher et hacher finement l''oignon et l''ail ; couper la carotte en petits dés.'),
  ('bolognaise', 2, 'Chauffer l''huile dans une grande casserole à feu moyen. Faire revenir l''oignon, la carotte et l''ail 5 minutes, jusqu''à ce que l''oignon soit translucide.'),
  ('bolognaise', 3, 'Monter à feu vif, ajouter la viande et la faire dorer 5 minutes en l''émiettant à la cuillère en bois, jusqu''à ce qu''elle ne soit plus rosée.'),
  ('bolognaise', 4, 'Ajouter le concentré de tomate et mélanger 1 minute, puis les tomates concassées et les herbes. Porter à frémissement et laisser mijoter 30 minutes à feu doux, à demi couvert, en remuant de temps en temps.'),
  ('bolognaise', 5, 'Dix minutes avant la fin, cuire les pâtes dans une grande casserole d''eau bouillante, 8 à 10 minutes (voir le paquet), puis les égoutter.'),
  ('bolognaise', 6, 'Servir la sauce sur les pâtes, avec le parmesan râpé.'),
  ('boulettes-boeuf-sauce-tomate', 1, 'Hacher finement l''oignon, l''ail et le persil. Dans un saladier, mélanger le bœuf, l''œuf, la chapelure, la moitié de l''oignon, l''ail et le persil ; saler et poivrer.'),
  ('boulettes-boeuf-sauce-tomate', 2, 'Former des boulettes de la taille d''une noix avec les mains légèrement humides.'),
  ('boulettes-boeuf-sauce-tomate', 3, 'Chauffer l''huile dans une sauteuse à feu moyen-vif et dorer les boulettes 5 minutes en les faisant rouler, jusqu''à ce qu''elles soient colorées de tous côtés.'),
  ('boulettes-boeuf-sauce-tomate', 4, 'Ajouter le reste d''oignon 2 minutes, puis verser le coulis. Couvrir et laisser mijoter 20 minutes à feu doux : les boulettes doivent être cuites à cœur.'),
  ('boulettes-boeuf-sauce-tomate', 5, 'Pendant ce temps, cuire les spaghetti dans une grande casserole d''eau bouillante 9 à 11 minutes (voir le paquet) et les égoutter.'),
  ('boulettes-boeuf-sauce-tomate', 6, 'Servir les spaghetti nappés de sauce et de boulettes, avec le parmesan.'),
  ('bowl-saumon-fume-avocat', 1, 'Rincer le riz, le cuire dans une casserole d''eau bouillante 11 à 12 minutes, l''égoutter et le laisser tiédir 10 minutes.'),
  ('bowl-saumon-fume-avocat', 2, 'Couper l''avocat en deux, retirer le noyau et le couper en dés ; couper le concombre et la mangue épluchée en dés. Détailler le saumon en lanières.'),
  ('bowl-saumon-fume-avocat', 3, 'Répartir le riz dans deux bols, puis disposer le saumon et les légumes en petits tas côte à côte.'),
  ('bowl-saumon-fume-avocat', 4, 'Mélanger la sauce soja avec le jus du citron vert, en arroser les bols et parsemer de sésame. Servir aussitôt pour que l''avocat ne noircisse pas.'),
  ('buddha-bowl-quinoa', 1, 'Préchauffer le four à 200 °C. Éplucher la patate douce et la couper en cubes d''environ 2 cm. Égoutter et rincer les pois chiches, puis bien les sécher.'),
  ('buddha-bowl-quinoa', 2, 'Sur la plaque du four, mélanger la patate douce et les pois chiches avec l''huile et le paprika, en une seule couche. Rôtir 30 minutes en remuant à mi-cuisson, jusqu''à ce que la patate douce soit tendre et dorée.'),
  ('buddha-bowl-quinoa', 3, 'Pendant ce temps, rincer le quinoa et le cuire 12 minutes à couvert dans une casserole avec deux fois son volume d''eau, à feu doux, jusqu''à absorption. Laisser gonfler 5 minutes hors du feu.'),
  ('buddha-bowl-quinoa', 4, 'Couper les avocats en tranches. Répartir le quinoa, les légumes rôtis, les épinards et l''avocat dans les bols.'),
  ('buddha-bowl-quinoa', 5, 'Arroser de jus de citron et parsemer de sésame.'),
  ('cabillaud-pane-haricots-verts', 1, 'Équeuter les haricots verts et les cuire 8 minutes dans une casserole d''eau bouillante salée : ils doivent rester légèrement croquants. Égoutter.'),
  ('cabillaud-pane-haricots-verts', 2, 'Éponger le poisson. Préparer trois assiettes creuses : la farine, l''œuf battu, la chapelure.'),
  ('cabillaud-pane-haricots-verts', 3, 'Passer chaque dos dans la farine, en tapotant pour retirer l''excédent, puis dans l''œuf, puis dans la chapelure en appuyant pour qu''elle adhère.'),
  ('cabillaud-pane-haricots-verts', 4, 'Chauffer l''huile dans une poêle à feu moyen. Cuire le poisson 4 minutes par face, jusqu''à ce que la panure soit dorée et que la chair s''effeuille au centre.'),
  ('cabillaud-pane-haricots-verts', 5, 'Servir avec les haricots verts et des quartiers de citron.'),
  ('cabillaud-poireaux', 1, 'Couper les poireaux en fines rondelles et les rincer soigneusement. Si vous servez des pommes de terre, les éplucher et les cuire 20 minutes à la vapeur.'),
  ('cabillaud-poireaux', 2, 'Faire fondre le beurre dans une sauteuse à feu doux, ajouter les poireaux, couvrir et laisser fondre 15 minutes en remuant de temps en temps, sans coloration.'),
  ('cabillaud-poireaux', 3, 'Ajouter la crème, saler, poivrer et laisser réduire 5 minutes à découvert, jusqu''à ce que la sauce nappe.'),
  ('cabillaud-poireaux', 4, 'Poser les dos de cabillaud sur les poireaux, saler légèrement, couvrir et cuire 8 minutes à feu doux : la chair doit devenir blanche et nacrée.'),
  ('cabillaud-poireaux', 5, 'Arroser de jus de citron et servir avec les pommes de terre vapeur.'),
  ('cake-banane', 1, 'Préchauffer le four à 180 °C. Beurrer un moule à cake avec une noisette du beurre. Faire fondre le reste du beurre.'),
  ('cake-banane', 2, 'Écraser les bananes à la fourchette en purée. Ajouter les œufs, le sucre et le beurre fondu et fouetter jusqu''à ce que le mélange soit homogène.'),
  ('cake-banane', 3, 'Incorporer la farine et la levure en mélangeant juste assez pour qu''il ne reste plus de traces de farine, puis ajouter les noix concassées.'),
  ('cake-banane', 4, 'Verser la pâte dans le moule à cake et enfourner 45 minutes : une lame plantée au centre doit ressortir sèche.'),
  ('cake-banane', 5, 'Laisser tiédir 10 minutes dans le moule, puis démouler sur une grille.'),
  ('chili-con-carne', 1, 'Éplucher et hacher les oignons et l''ail ; couper le poivron en petits dés.'),
  ('chili-con-carne', 2, 'Chauffer l''huile dans une cocotte à feu moyen. Faire revenir les oignons, le poivron et l''ail 5 minutes, jusqu''à ce qu''ils soient tendres.'),
  ('chili-con-carne', 3, 'Monter à feu vif, ajouter le bœuf et le faire colorer 5 minutes en l''émiettant. Ajouter le cumin, le paprika et le piment, mélanger 1 minute.'),
  ('chili-con-carne', 4, 'Ajouter les tomates et les haricots rincés, saler, porter à frémissement et laisser mijoter 40 minutes à feu doux, à demi couvert, en remuant de temps en temps.'),
  ('chili-con-carne', 5, 'Pendant ce temps, cuire le riz dans une casserole d''eau bouillante 11 à 12 minutes et l''égoutter. Servir le chili sur le riz.'),
  ('chili-sin-carne', 1, 'Éplucher et hacher l''oignon et l''ail ; couper le poivron en dés.'),
  ('chili-sin-carne', 2, 'Chauffer l''huile dans une cocotte à feu moyen et faire revenir l''oignon, l''ail et le poivron 5 minutes, jusqu''à ce qu''ils soient tendres.'),
  ('chili-sin-carne', 3, 'Ajouter le cumin, le paprika et le piment et remuer 1 minute, puis verser les tomates. Laisser mijoter 15 minutes à feu doux.'),
  ('chili-sin-carne', 4, 'Rincer et égoutter les haricots et le maïs, les ajouter et cuire encore 15 minutes, jusqu''à ce que la sauce épaississe.'),
  ('chili-sin-carne', 5, 'Pendant ce temps, cuire le riz dans une casserole d''eau bouillante 11 à 12 minutes. Servir le chili avec le riz.'),
  ('chou-fleur-roti-curry', 1, 'Préchauffer le four à 210 °C. Détailler le chou-fleur en fleurettes de taille égale. Égoutter, rincer et sécher les pois chiches.'),
  ('chou-fleur-roti-curry', 2, 'Sur la plaque du four, mélanger le chou-fleur et les pois chiches avec l''huile, le curry et le sel, en une seule couche.'),
  ('chou-fleur-roti-curry', 3, 'Rôtir 35 minutes en remuant à mi-cuisson, jusqu''à ce que le chou-fleur soit tendre et bien doré sur les bords.'),
  ('chou-fleur-roti-curry', 4, 'Pendant ce temps, cuire le riz dans une casserole d''eau bouillante 11 à 12 minutes. Mélanger le yaourt avec le jus du citron et une pincée de sel.'),
  ('chou-fleur-roti-curry', 5, 'Servir le chou-fleur et les pois chiches sur le riz, avec la sauce au yaourt et la coriandre ciselée.'),
  ('coquillettes-jambon-emmental', 1, 'Porter une grande casserole d''eau à ébullition et cuire les coquillettes 8 à 10 minutes (voir le paquet).'),
  ('coquillettes-jambon-emmental', 2, 'Pendant ce temps, couper le jambon en petits dés.'),
  ('coquillettes-jambon-emmental', 3, 'Égoutter les coquillettes et les remettre aussitôt dans la casserole hors du feu, avec le beurre.'),
  ('coquillettes-jambon-emmental', 4, 'Ajouter le jambon et l''emmental et mélanger 1 minute à feu doux, jusqu''à ce que le fromage file. Poivrer et servir.'),
  ('cotes-porc-pommes', 1, 'Si vous servez des pommes de terre, les éplucher et les cuire 20 minutes à la vapeur. Couper les pommes en quartiers et émincer l''oignon.'),
  ('cotes-porc-pommes', 2, 'Faire fondre la moitié du beurre dans une poêle à feu moyen-vif. Dorer les côtes 5 minutes par face, saler, poivrer, puis les réserver au chaud sur une assiette couverte.'),
  ('cotes-porc-pommes', 3, 'Dans la même poêle, faire fondre le reste du beurre et faire caraméliser les pommes et l''oignon 8 minutes à feu moyen, jusqu''à ce qu''ils soient dorés et tendres.'),
  ('cotes-porc-pommes', 4, 'Ajouter la moutarde et la crème, mélanger, puis remettre les côtes et leur jus 5 minutes à feu doux, en les nappant de sauce.'),
  ('cotes-porc-pommes', 5, 'Servir avec les pommes de terre vapeur.'),
  ('courgettes-farcies-boulgour', 1, 'Préchauffer le four à 190 °C. Cuire le boulgour 10 minutes dans une casserole avec deux fois son volume d''eau, à couvert, puis l''égrener.'),
  ('courgettes-farcies-boulgour', 2, 'Couper les courgettes en deux dans la longueur et les évider avec une petite cuillère en laissant un bord d''environ 5 mm. Hacher la chair et l''oignon.'),
  ('courgettes-farcies-boulgour', 3, 'Chauffer l''huile dans une poêle à feu moyen, faire revenir l''oignon et la chair des courgettes 5 minutes, puis ajouter les tomates et cuire encore 5 minutes. Saler et poivrer.'),
  ('courgettes-farcies-boulgour', 4, 'Hors du feu, mélanger avec le boulgour, la feta émiettée et la menthe ciselée. Garnir généreusement les courgettes et les ranger dans un plat allant au four.'),
  ('courgettes-farcies-boulgour', 5, 'Enfourner 30 minutes, jusqu''à ce que les courgettes soient tendres sous la pointe d''un couteau et le dessus doré.'),
  ('couscous-legumes', 1, 'Éplucher l''oignon et l''émincer ; éplucher les carottes et le navet et les couper en gros tronçons ; couper les courgettes en gros morceaux.'),
  ('couscous-legumes', 2, 'Chauffer l''huile dans un faitout à feu moyen, faire revenir l''oignon 3 minutes avec le cumin.'),
  ('couscous-legumes', 3, 'Ajouter les carottes, le navet, les tomates, le cube émietté et l''eau. Porter à ébullition, puis couvrir et cuire 20 minutes à feu moyen-doux.'),
  ('couscous-legumes', 4, 'Ajouter les courgettes et les pois chiches rincés et cuire encore 15 minutes, jusqu''à ce que tous les légumes soient tendres.'),
  ('couscous-legumes', 5, 'Préparer la semoule : la verser dans un saladier, la couvrir du même volume d''eau bouillante, couvrir 5 minutes puis l''égrener à la fourchette.'),
  ('couscous-legumes', 6, 'Servir la semoule avec les légumes et leur bouillon, et la harissa à part.'),
  ('crepes-jambon-fromage', 1, 'Dans un saladier, mélanger la farine et une pincée de sel. Creuser un puits, y casser les œufs et fouetter en incorporant la farine petit à petit.'),
  ('crepes-jambon-fromage', 2, 'Verser le lait progressivement en fouettant pour éviter les grumeaux, puis ajouter la moitié du beurre fondu. Laisser reposer 30 minutes si possible.'),
  ('crepes-jambon-fromage', 3, 'Chauffer une poêle à feu moyen-vif et la graisser légèrement avec le reste du beurre. Verser une petite louche de pâte en inclinant la poêle pour couvrir le fond, cuire 1 minute, retourner et cuire 30 secondes.'),
  ('crepes-jambon-fromage', 4, 'Remettre une crêpe dans la poêle, garnir d''une tranche de jambon et d''emmental, plier en quatre et laisser fondre 1 minute. Recommencer avec les autres.'),
  ('crepes-jambon-fromage', 5, 'Servir chaud avec la salade.'),
  ('crevettes-curry-coco', 1, 'Cuire le riz dans une casserole d''eau bouillante 10 à 12 minutes, puis l''égoutter. Émincer l''oignon et couper le poivron en lanières.'),
  ('crevettes-curry-coco', 2, 'Chauffer l''huile dans une sauteuse à feu moyen et faire revenir l''oignon et le poivron 5 minutes.'),
  ('crevettes-curry-coco', 3, 'Ajouter la pâte de curry et remuer 1 minute, jusqu''à ce qu''elle embaume.'),
  ('crevettes-curry-coco', 4, 'Verser le lait de coco, porter à frémissement 5 minutes, puis ajouter les crevettes et cuire 3 à 4 minutes, jusqu''à ce qu''elles soient roses et opaques.'),
  ('crevettes-curry-coco', 5, 'Hors du feu, ajouter le jus du citron vert et la coriandre ciselée. Servir avec le riz.'),
  ('croque-monsieur', 1, 'Préchauffer le four à 220 °C.'),
  ('croque-monsieur', 2, 'Beurrer une face de chaque tranche de pain. Poser la moitié des tranches sur la plaque, face beurrée dessous, et garnir chacune d''une tranche de jambon et d''emmental.'),
  ('croque-monsieur', 3, 'Refermer avec les autres tranches, face beurrée dessus, et parsemer du reste d''emmental.'),
  ('croque-monsieur', 4, 'Enfourner 10 minutes, jusqu''à ce que le fromage soit fondu et le pain bien doré.'),
  ('crumble-pommes', 1, 'Préchauffer le four à 180 °C. Éplucher les pommes, les couper en morceaux et les répartir dans un plat allant au four. Les saupoudrer de cannelle.'),
  ('crumble-pommes', 2, 'Dans un saladier, mélanger la farine et le sucre, puis ajouter le beurre froid coupé en dés.'),
  ('crumble-pommes', 3, 'Sabler du bout des doigts jusqu''à obtenir une pâte en grosses miettes irrégulières, sans la pétrir.'),
  ('crumble-pommes', 4, 'Parsemer la pâte sur les pommes sans tasser.'),
  ('crumble-pommes', 5, 'Enfourner 35 minutes, jusqu''à ce que le dessus soit bien doré et que le jus des pommes bouillonne sur les bords. Servir tiède.'),
  ('curry-pois-chiches-epinards', 1, 'Hacher l''oignon et l''ail, râper le gingembre. Cuire le riz dans une casserole d''eau bouillante 11 à 12 minutes.'),
  ('curry-pois-chiches-epinards', 2, 'Chauffer l''huile dans une sauteuse à feu moyen et faire revenir l''oignon, l''ail et le gingembre 5 minutes, jusqu''à ce que l''oignon soit tendre.'),
  ('curry-pois-chiches-epinards', 3, 'Ajouter le curry et remuer 1 minute, puis verser les tomates et le lait de coco.'),
  ('curry-pois-chiches-epinards', 4, 'Ajouter les pois chiches rincés, porter à frémissement et laisser mijoter 15 minutes à feu doux, jusqu''à ce que la sauce épaississe.'),
  ('curry-pois-chiches-epinards', 5, 'Incorporer les épinards en fin de cuisson et remuer 1 à 2 minutes, jusqu''à ce qu''ils tombent.'),
  ('curry-pois-chiches-epinards', 6, 'Servir avec le riz et la coriandre ciselée.'),
  ('dinde-creme-champignons', 1, 'Cuire le riz dans une casserole d''eau bouillante 11 à 12 minutes. Émincer les échalotes et couper les champignons en lamelles.'),
  ('dinde-creme-champignons', 2, 'Faire fondre la moitié du beurre dans une poêle à feu moyen-vif. Dorer les escalopes 3 minutes par face, saler, poivrer et les réserver sur une assiette.'),
  ('dinde-creme-champignons', 3, 'Dans la même poêle, faire fondre le reste du beurre et faire revenir les échalotes et les champignons 5 minutes, jusqu''à ce que leur eau s''évapore.'),
  ('dinde-creme-champignons', 4, 'Ajouter la crème et laisser réduire 3 minutes à feu moyen, jusqu''à ce que la sauce nappe la cuillère.'),
  ('dinde-creme-champignons', 5, 'Remettre la dinde et son jus dans la sauce 2 minutes pour la réchauffer. Parsemer de persil et servir avec le riz.'),
  ('endives-jambon', 1, 'Préchauffer le four à 200 °C. Retirer le cône dur à la base des endives et les cuire 20 minutes à la vapeur. Les presser fermement entre les mains pour retirer un maximum d''eau.'),
  ('endives-jambon', 2, 'Préparer la béchamel : faire fondre le beurre dans une casserole à feu moyen, ajouter la farine et remuer 2 minutes. Verser le lait petit à petit en fouettant et cuire 5 minutes jusqu''à épaississement. Assaisonner de muscade, sel et poivre.'),
  ('endives-jambon', 3, 'Rouler chaque endive dans une tranche de jambon et les ranger côte à côte dans un plat allant au four.'),
  ('endives-jambon', 4, 'Napper de béchamel et couvrir d''emmental.'),
  ('endives-jambon', 5, 'Enfourner 20 minutes, jusqu''à ce que le dessus soit bien gratiné.'),
  ('fajitas-poulet', 1, 'Dans un saladier, mélanger les lanières de poulet avec le paprika, le cumin et le jus du citron vert. Laisser mariner pendant la découpe des légumes.'),
  ('fajitas-poulet', 2, 'Épépiner les poivrons et les couper en lanières ; émincer l''oignon rouge.'),
  ('fajitas-poulet', 3, 'Chauffer l''huile dans une grande poêle à feu vif. Faire sauter le poulet 5 à 6 minutes, jusqu''à ce qu''il soit doré et cuit à cœur, puis le réserver.'),
  ('fajitas-poulet', 4, 'Dans la même poêle, faire sauter les poivrons et l''oignon 5 minutes à feu vif : ils doivent rester légèrement croquants. Remettre le poulet et mélanger.'),
  ('fajitas-poulet', 5, 'Réchauffer les tortillas 20 secondes de chaque côté dans une poêle sèche à feu moyen.'),
  ('fajitas-poulet', 6, 'Garnir chaque tortilla de poulet et de légumes, ajouter la crème, le cheddar râpé et quelques feuilles de salade, puis rouler.'),
  ('falafels-four', 1, 'Préchauffer le four à 200 °C. Égoutter, rincer et bien sécher les pois chiches.'),
  ('falafels-four', 2, 'Mixer les pois chiches avec l''oignon, l''ail, le persil, la coriandre, le cumin, la farine et le sel, par à-coups, jusqu''à obtenir une pâte grossière qui se tient quand on la presse.'),
  ('falafels-four', 3, 'Former des boulettes de la taille d''une noix, les aplatir légèrement et les poser sur une plaque huilée. Les badigeonner d''huile.'),
  ('falafels-four', 4, 'Cuire 25 minutes en les retournant à mi-cuisson, jusqu''à ce qu''elles soient dorées et fermes.'),
  ('falafels-four', 5, 'Pendant ce temps, mélanger les yaourts avec le jus du citron et une pincée de sel. Servir les falafels avec la sauce et la salade.'),
  ('farfalle-saumon-epinards', 1, 'Porter une grande casserole d''eau à ébullition et cuire les farfalle 10 à 12 minutes (voir le paquet).'),
  ('farfalle-saumon-epinards', 2, 'Pendant ce temps, prélever le zeste du citron puis le presser.'),
  ('farfalle-saumon-epinards', 3, 'Dans une poêle à feu moyen, faire tomber les épinards avec la crème 3 minutes en remuant.'),
  ('farfalle-saumon-epinards', 4, 'Ajouter le zeste et un filet de jus de citron, poivrer et retirer du feu.'),
  ('farfalle-saumon-epinards', 5, 'Égoutter les pâtes, les mélanger à la sauce puis ajouter le saumon en lanières au dernier moment, pour qu''il ne cuise pas.'),
  ('filet-mignon-miel-moutarde', 1, 'Préchauffer le four à 190 °C. Éplucher les carottes et les couper en bâtonnets.'),
  ('filet-mignon-miel-moutarde', 2, 'Mélanger le miel et la moutarde. Saler et poivrer le filet, puis le badigeonner de ce mélange.'),
  ('filet-mignon-miel-moutarde', 3, 'Poser le filet dans un plat allant au four, disposer les carottes autour, arroser d''huile et parsemer de thym.'),
  ('filet-mignon-miel-moutarde', 4, 'Enfourner 35 minutes en arrosant le filet de son jus à mi-cuisson : la viande doit être juste rosée au centre et les carottes tendres.'),
  ('filet-mignon-miel-moutarde', 5, 'Couvrir et laisser reposer 5 minutes hors du four, puis trancher en médaillons et servir avec les carottes et le jus.'),
  ('frittata-legumes', 1, 'Préchauffer le four à 180 °C. Émincer l''oignon, couper la courgette en fines demi-rondelles et les pommes de terre cuites en dés.'),
  ('frittata-legumes', 2, 'Chauffer l''huile à feu moyen dans une poêle allant au four. Faire revenir l''oignon et la courgette 5 minutes, puis les pommes de terre 3 minutes, jusqu''à ce qu''elles dorent.'),
  ('frittata-legumes', 3, 'Battre les œufs avec l''emmental, du sel et du poivre.'),
  ('frittata-legumes', 4, 'Verser les œufs sur les légumes, répartir et cuire 5 minutes à feu doux sans remuer, jusqu''à ce que les bords prennent.'),
  ('frittata-legumes', 5, 'Glisser la poêle au four 12 à 15 minutes : le centre doit être pris et le dessus doré. Laisser tiédir 2 minutes avant de couper en parts.'),
  ('fusilli-pesto-poulet', 1, 'Porter une grande casserole d''eau à ébullition, saler et cuire les fusilli 10 à 12 minutes (voir le paquet).'),
  ('fusilli-pesto-poulet', 2, 'Pendant ce temps, chauffer l''huile dans une poêle à feu moyen-vif et dorer le poulet 8 minutes en remuant, jusqu''à ce qu''il soit cuit à cœur. Saler, poivrer.'),
  ('fusilli-pesto-poulet', 3, 'Couper les tomates cerises en deux.'),
  ('fusilli-pesto-poulet', 4, 'Égoutter les pâtes en gardant un peu d''eau de cuisson. Hors du feu, les mélanger avec le pesto, le poulet et les tomates ; ajouter un filet d''eau de cuisson si c''est trop épais.'),
  ('fusilli-pesto-poulet', 5, 'Servir avec le parmesan râpé.'),
  ('galettes-pommes-de-terre', 1, 'Éplucher et râper les pommes de terre et l''oignon. Les presser fortement dans un torchon propre pour retirer le maximum d''eau.'),
  ('galettes-pommes-de-terre', 2, 'Dans un saladier, mélanger avec les œufs, la farine et le sel.'),
  ('galettes-pommes-de-terre', 3, 'Chauffer l''huile dans une grande poêle à feu moyen-vif. Déposer des cuillerées de mélange et les aplatir en galettes d''environ 1 cm.'),
  ('galettes-pommes-de-terre', 4, 'Cuire 4 minutes de chaque côté, jusqu''à ce qu''elles soient bien dorées et croustillantes. Les égoutter sur une assiette.'),
  ('galettes-pommes-de-terre', 5, 'Mélanger le fromage blanc avec la ciboulette ciselée et une pincée de sel. Servir les galettes chaudes avec la sauce et la salade.'),
  ('gaspacho', 1, 'Laver les légumes. Couper les tomates en quartiers, éplucher le concombre, épépiner le poivron, éplucher l''oignon et l''ail, puis tout couper en morceaux.'),
  ('gaspacho', 2, 'Mixer les légumes avec l''huile, le vinaigre, le pain et le sel pendant 2 minutes, jusqu''à obtenir une soupe bien lisse.'),
  ('gaspacho', 3, 'Goûter et rectifier l''assaisonnement ; détendre avec un peu d''eau froide si la soupe est trop épaisse.'),
  ('gaspacho', 4, 'Réfrigérer au moins 1 heure et servir bien frais.'),
  ('gnocchis-epinards-lardons', 1, 'Dans une grande poêle à feu moyen, faire dorer les lardons à sec 4 minutes, jusqu''à ce qu''ils rendent leur graisse.'),
  ('gnocchis-epinards-lardons', 2, 'Ajouter les gnocchis et les faire dorer 6 minutes dans la graisse des lardons, en remuant de temps en temps.'),
  ('gnocchis-epinards-lardons', 3, 'Ajouter les épinards et remuer 2 minutes, jusqu''à ce qu''ils tombent.'),
  ('gnocchis-epinards-lardons', 4, 'Verser la crème et le parmesan râpé, mélanger 1 minute pour napper les gnocchis. Poivrer et servir aussitôt.'),
  ('gnocchis-pesto', 1, 'Chauffer l''huile dans une poêle à feu moyen-vif. Faire dorer les gnocchis 6 à 8 minutes en les remuant de temps en temps, jusqu''à ce qu''ils soient croustillants.'),
  ('gnocchis-pesto', 2, 'Couper les tomates cerises en deux, les ajouter et cuire 2 minutes, juste pour qu''elles s''attendrissent.'),
  ('gnocchis-pesto', 3, 'Hors du feu, mélanger avec le pesto et servir avec le parmesan râpé.'),
  ('gratin-chou-fleur', 1, 'Préchauffer le four à 200 °C. Cuire les fleurettes de chou-fleur 10 minutes dans une casserole d''eau bouillante salée : elles doivent rester un peu fermes. Bien égoutter.'),
  ('gratin-chou-fleur', 2, 'Préparer la béchamel : faire fondre le beurre dans une casserole à feu moyen, ajouter la farine et remuer 2 minutes. Verser le lait petit à petit en fouettant et cuire 5 minutes jusqu''à épaississement. Assaisonner de muscade, sel et poivre.'),
  ('gratin-chou-fleur', 3, 'Disposer le chou-fleur dans un plat à gratin, napper de béchamel et couvrir d''emmental.'),
  ('gratin-chou-fleur', 4, 'Enfourner 20 minutes, jusqu''à ce que le dessus soit bien doré.'),
  ('gratin-courgettes', 1, 'Préchauffer le four à 190 °C. Couper les courgettes en rondelles fines et hacher l''ail.'),
  ('gratin-courgettes', 2, 'Chauffer l''huile dans une poêle à feu moyen et faire revenir les courgettes avec l''ail 10 minutes, jusqu''à ce qu''elles aient rendu leur eau. Les égoutter.'),
  ('gratin-courgettes', 3, 'Battre les œufs avec la crème, saler et poivrer.'),
  ('gratin-courgettes', 4, 'Répartir les courgettes dans un plat à gratin, verser le mélange et couvrir d''emmental.'),
  ('gratin-courgettes', 5, 'Enfourner 25 minutes, jusqu''à ce que l''appareil soit pris et le dessus doré.'),
  ('gratin-dauphinois', 1, 'Préchauffer le four à 180 °C. Frotter un plat à gratin avec la gousse d''ail coupée en deux, puis le beurrer.'),
  ('gratin-dauphinois', 2, 'Éplucher les pommes de terre et les couper en rondelles fines d''environ 3 mm, sans les rincer : leur amidon épaissira la sauce.'),
  ('gratin-dauphinois', 3, 'Dans une grande casserole, chauffer le lait et la crème avec du sel, du poivre et la muscade.'),
  ('gratin-dauphinois', 4, 'Ajouter les pommes de terre et cuire 10 minutes à feu doux en remuant délicatement, jusqu''à ce que le liquide épaississe.'),
  ('gratin-dauphinois', 5, 'Verser dans le plat et enfourner 50 minutes, jusqu''à ce que le dessus soit doré et que la pointe d''un couteau traverse les pommes de terre sans résistance.'),
  ('gratin-pates-brocoli', 1, 'Préchauffer le four à 200 °C. Dans une grande casserole d''eau bouillante salée, cuire les pâtes 4 minutes, ajouter le brocoli et cuire encore 4 minutes. Égoutter.'),
  ('gratin-pates-brocoli', 2, 'Battre la crème avec les œufs, la muscade, le sel et le poivre.'),
  ('gratin-pates-brocoli', 3, 'Verser les pâtes et le brocoli dans un plat à gratin, napper du mélange et couvrir d''emmental.'),
  ('gratin-pates-brocoli', 4, 'Enfourner 20 minutes, jusqu''à ce que le dessus soit gratiné.'),
  ('gratin-poireaux-jambon', 1, 'Préchauffer le four à 200 °C. Couper les poireaux en tronçons de 4 cm, les rincer et les cuire 15 minutes à la vapeur. Bien les égoutter.'),
  ('gratin-poireaux-jambon', 2, 'Préparer la béchamel : faire fondre le beurre dans une casserole à feu moyen, ajouter la farine et remuer 2 minutes. Verser le lait petit à petit en fouettant et cuire 5 minutes jusqu''à épaississement. Assaisonner de muscade, sel et poivre.'),
  ('gratin-poireaux-jambon', 3, 'Couper le jambon en lanières. Disposer les poireaux et le jambon dans un plat à gratin.'),
  ('gratin-poireaux-jambon', 4, 'Napper de béchamel, couvrir d''emmental et enfourner 20 minutes, jusqu''à ce que le dessus soit doré.'),
  ('hachis-parmentier', 1, 'Éplucher les pommes de terre, les couper en morceaux et les cuire 20 minutes dans une casserole d''eau froide salée portée à ébullition : la pointe d''un couteau doit s''y enfoncer facilement.'),
  ('hachis-parmentier', 2, 'Préchauffer le four à 200 °C. Égoutter les pommes de terre et les écraser avec le lait chaud et la moitié du beurre ; saler et poivrer.'),
  ('hachis-parmentier', 3, 'Pendant la cuisson des pommes de terre, émincer les oignons et les faire revenir 5 minutes dans le reste du beurre, dans une poêle à feu moyen.'),
  ('hachis-parmentier', 4, 'Ajouter la viande et le concentré de tomate et cuire 10 minutes en émiettant, jusqu''à ce que la viande soit bien colorée. Saler et poivrer.'),
  ('hachis-parmentier', 5, 'Étaler la viande dans un plat à gratin, recouvrir de purée en lissant à la fourchette et parsemer d''emmental.'),
  ('hachis-parmentier', 6, 'Enfourner 25 minutes, jusqu''à ce que le dessus soit bien doré.'),
  ('lasagnes-bolognaise', 1, 'Chauffer l''huile dans une sauteuse à feu moyen et faire revenir l''oignon, la carotte et l''ail hachés 5 minutes. Ajouter le bœuf et le faire colorer 5 minutes en l''émiettant.'),
  ('lasagnes-bolognaise', 2, 'Verser le coulis, saler, poivrer et laisser mijoter 20 minutes à feu doux.'),
  ('lasagnes-bolognaise', 3, 'Préchauffer le four à 180 °C. Préparer la béchamel : faire fondre le beurre dans une casserole, ajouter la farine et remuer 2 minutes, puis verser le lait petit à petit en fouettant et cuire 5 minutes jusqu''à épaississement. Ajouter la muscade, saler.'),
  ('lasagnes-bolognaise', 4, 'Dans un plat allant au four, étaler une fine couche de sauce, puis alterner pâtes, sauce et béchamel ; terminer par la béchamel et l''emmental.'),
  ('lasagnes-bolognaise', 5, 'Enfourner 40 minutes, jusqu''à ce que le dessus soit doré et que les pâtes soient tendres sous la pointe d''un couteau. Laisser reposer 10 minutes avant de couper.'),
  ('lasagnes-epinards-ricotta', 1, 'Préchauffer le four à 180 °C. Hacher l''ail et faire tomber les épinards avec l''ail 3 à 4 minutes dans une poêle à feu moyen.'),
  ('lasagnes-epinards-ricotta', 2, 'Égoutter les épinards en les pressant bien, puis les hacher grossièrement.'),
  ('lasagnes-epinards-ricotta', 3, 'Mélanger les épinards avec la ricotta, la moitié du parmesan, la muscade, du sel et du poivre.'),
  ('lasagnes-epinards-ricotta', 4, 'Dans un plat allant au four, étaler une couche de coulis, puis alterner pâtes, coulis et mélange épinards-ricotta.'),
  ('lasagnes-epinards-ricotta', 5, 'Terminer par une couche de pâtes, du coulis, la mozzarella en tranches et le reste du parmesan.'),
  ('lasagnes-epinards-ricotta', 6, 'Enfourner 40 minutes, jusqu''à ce que le dessus soit doré et bouillonnant. Laisser reposer 10 minutes avant de couper.'),
  ('lentilles-corail-dahl', 1, 'Hacher l''oignon et l''ail, râper le gingembre. Rincer les lentilles jusqu''à ce que l''eau soit claire.'),
  ('lentilles-corail-dahl', 2, 'Chauffer l''huile dans une casserole à feu moyen et faire revenir l''oignon, l''ail et le gingembre 5 minutes.'),
  ('lentilles-corail-dahl', 3, 'Ajouter le curcuma et le cumin et remuer 1 minute, puis les lentilles, les tomates, le lait de coco et l''eau.'),
  ('lentilles-corail-dahl', 4, 'Porter à frémissement et cuire 20 à 25 minutes à feu doux en remuant souvent pour que rien n''attache, jusqu''à ce que les lentilles se défassent en purée.'),
  ('lentilles-corail-dahl', 5, 'Ajouter un trait de jus de citron vert avant de servir.'),
  ('lentilles-vertes-legumes', 1, 'Rincer les lentilles. Couper l''oignon, les carottes et le céleri en petits dés ; écraser l''ail.'),
  ('lentilles-vertes-legumes', 2, 'Chauffer l''huile dans une casserole à feu moyen et faire revenir l''oignon, les carottes et le céleri 5 minutes.'),
  ('lentilles-vertes-legumes', 3, 'Ajouter les lentilles, l''ail, le laurier, le thym, l''eau et le cube émietté. Porter à ébullition.'),
  ('lentilles-vertes-legumes', 4, 'Cuire 30 minutes à petit frémissement, à demi couvert : les lentilles doivent être tendres mais encore entières. Saler en fin de cuisson seulement.'),
  ('lentilles-vertes-legumes', 5, 'Égoutter l''excédent de liquide si besoin et ajouter la moutarde au moment de servir.'),
  ('linguine-crevettes-ail', 1, 'Porter une grande casserole d''eau à ébullition, saler et cuire les linguine 9 à 11 minutes (voir le paquet). Prélever le zeste du citron et le presser ; ciseler le persil.'),
  ('linguine-crevettes-ail', 2, 'Pendant ce temps, chauffer l''huile dans une grande poêle à feu doux avec l''ail émincé et le piment 2 minutes, sans laisser l''ail brunir.'),
  ('linguine-crevettes-ail', 3, 'Monter à feu vif, ajouter les crevettes et les saisir 3 minutes, jusqu''à ce qu''elles soient roses.'),
  ('linguine-crevettes-ail', 4, 'Ajouter le zeste et le jus du citron, puis les pâtes égouttées et une petite louche d''eau de cuisson. Mélanger 1 minute pour bien enrober.'),
  ('linguine-crevettes-ail', 5, 'Parsemer de persil et servir aussitôt.'),
  ('macaronis-gratines', 1, 'Préchauffer le four à 200 °C. Cuire les macaronis dans une grande casserole d''eau bouillante salée 2 minutes de moins que l''indication du paquet, puis les égoutter.'),
  ('macaronis-gratines', 2, 'Préparer la béchamel : faire fondre le beurre dans une casserole à feu moyen, ajouter la farine et remuer 2 minutes, puis verser le lait petit à petit en fouettant et cuire 5 minutes jusqu''à épaississement.'),
  ('macaronis-gratines', 3, 'Hors du feu, ajouter le cheddar et la muscade et remuer jusqu''à ce que le fromage fonde. Saler.'),
  ('macaronis-gratines', 4, 'Mélanger avec les pâtes et verser dans un plat à gratin. Couvrir d''emmental et de chapelure.'),
  ('macaronis-gratines', 5, 'Enfourner 20 minutes, jusqu''à ce que le dessus soit doré et croustillant.'),
  ('merguez-semoule-legumes', 1, 'Émincer l''oignon ; éplucher les carottes et les couper en rondelles ; couper les courgettes en gros dés.'),
  ('merguez-semoule-legumes', 2, 'Dans une casserole, mettre les carottes, l''oignon, les tomates, le cumin, l''eau et le cube émietté. Porter à ébullition puis cuire 10 minutes à couvert à feu moyen.'),
  ('merguez-semoule-legumes', 3, 'Ajouter les courgettes et cuire encore 10 minutes, puis les pois chiches rincés pendant les 5 dernières minutes.'),
  ('merguez-semoule-legumes', 4, 'Pendant ce temps, cuire les merguez 10 à 12 minutes dans une poêle à feu moyen, en les retournant régulièrement, jusqu''à ce qu''elles soient bien dorées.'),
  ('merguez-semoule-legumes', 5, 'Préparer la semoule : la couvrir du même volume d''eau bouillante, couvrir 5 minutes, puis l''égrener à la fourchette.'),
  ('merguez-semoule-legumes', 6, 'Servir la semoule avec les légumes, leur bouillon, les merguez et la harissa à part.'),
  ('minestrone', 1, 'Couper l''oignon, les carottes et le céleri en petits dés, et la courgette en dés un peu plus gros.'),
  ('minestrone', 2, 'Chauffer l''huile dans un faitout à feu moyen et faire revenir l''oignon, les carottes et le céleri 5 minutes.'),
  ('minestrone', 3, 'Ajouter la courgette, les tomates, l''eau et les cubes émiettés. Porter à ébullition et cuire 20 minutes à frémissement.'),
  ('minestrone', 4, 'Ajouter les haricots rincés et les coquillettes et cuire encore 10 minutes, jusqu''à ce que les pâtes soient tendres.'),
  ('minestrone', 5, 'Servir avec le parmesan râpé et le basilic ciselé.'),
  ('moules-marinieres', 1, 'Rincer les moules à l''eau froide et jeter celles qui sont cassées ou qui restent ouvertes quand on les tapote. Hacher les échalotes et le persil.'),
  ('moules-marinieres', 2, 'Dans une grande cocotte, faire fondre les échalotes dans le beurre 3 minutes à feu moyen, sans coloration.'),
  ('moules-marinieres', 3, 'Monter à feu vif, verser le vin et ajouter les moules. Couvrir et cuire 6 à 8 minutes en secouant la cocotte deux ou trois fois, jusqu''à ce qu''elles soient toutes ouvertes.'),
  ('moules-marinieres', 4, 'Ajouter le persil et la crème, poivrer et mélanger. Jeter les moules restées fermées.'),
  ('moules-marinieres', 5, 'Servir aussitôt dans des bols avec le jus, et le pain pour saucer.'),
  ('mousse-chocolat', 1, 'Casser le chocolat en morceaux et le faire fondre au bain-marie, dans un bol posé sur une casserole d''eau frémissante, en remuant. Le laisser tiédir 5 minutes.'),
  ('mousse-chocolat', 2, 'Séparer les blancs des jaunes. Incorporer les jaunes un à un au chocolat tiède en mélangeant vivement.'),
  ('mousse-chocolat', 3, 'Monter les blancs en neige ferme dans un grand saladier, en ajoutant le sucre en pluie quand ils commencent à mousser.'),
  ('mousse-chocolat', 4, 'Incorporer un tiers des blancs au chocolat en fouettant pour l''assouplir, puis le reste délicatement à la spatule, en soulevant la masse, jusqu''à ce qu''il n''y ait plus de traces blanches.'),
  ('mousse-chocolat', 5, 'Répartir dans des ramequins ou un saladier et réfrigérer au moins 4 heures.'),
  ('nouilles-sautees-tofu', 1, 'Réhydrater les nouilles dans un saladier d''eau chaude 5 à 8 minutes (voir le paquet), jusqu''à ce qu''elles soient souples. Les égoutter et les rincer à l''eau froide.'),
  ('nouilles-sautees-tofu', 2, 'Couper les carottes en julienne, le poivron en lanières et l''oignon en fines lamelles ; râper le gingembre. Éponger le tofu et le couper en cubes.'),
  ('nouilles-sautees-tofu', 3, 'Chauffer la moitié de l''huile dans un wok ou une grande poêle à feu vif. Dorer le tofu 5 minutes en le retournant, jusqu''à ce qu''il soit croustillant sur toutes les faces. Réserver.'),
  ('nouilles-sautees-tofu', 4, 'Ajouter le reste d''huile et faire sauter les légumes et le gingembre 4 minutes à feu vif : ils doivent rester croquants.'),
  ('nouilles-sautees-tofu', 5, 'Ajouter les nouilles, le tofu, la sauce soja et le sucre, et mélanger 2 minutes à feu vif. Parsemer de cacahuètes concassées et servir.'),
  ('oeufs-cocotte', 1, 'Préchauffer le four à 180 °C et faire chauffer de l''eau. Beurrer 4 ramequins avec une partie du beurre.'),
  ('oeufs-cocotte', 2, 'Répartir la crème et les dés de jambon dans les ramequins, puis casser délicatement un œuf dans chacun. Saler et poivrer.'),
  ('oeufs-cocotte', 3, 'Poser les ramequins dans un plat allant au four et verser de l''eau chaude jusqu''à mi-hauteur des ramequins.'),
  ('oeufs-cocotte', 4, 'Enfourner 12 minutes : le blanc doit être pris et le jaune encore coulant.'),
  ('oeufs-cocotte', 5, 'Pendant ce temps, couper le pain en mouillettes, les tartiner du reste de beurre et les faire griller. Parsemer les œufs de ciboulette ciselée et servir aussitôt.'),
  ('omelette-champignons', 1, 'Faire fondre le beurre dans une poêle à feu moyen-vif. Ajouter les champignons et les faire dorer 5 minutes, jusqu''à ce que leur eau soit évaporée. Saler.'),
  ('omelette-champignons', 2, 'Battre les œufs avec la crème, du sel et du poivre, juste assez pour mélanger blancs et jaunes.'),
  ('omelette-champignons', 3, 'Baisser à feu doux et verser les œufs sur les champignons. Ramener les bords vers le centre avec une spatule pendant 2 à 3 minutes, puis laisser cuire sans toucher jusqu''à ce que le dessus soit encore légèrement baveux.'),
  ('omelette-champignons', 4, 'Plier l''omelette en deux, la faire glisser sur une assiette, parsemer de persil et servir.'),
  ('one-pot-pasta-legumes', 1, 'Couper la courgette en dés, émincer l''oignon, émincer l''ail et couper les tomates cerises en deux.'),
  ('one-pot-pasta-legumes', 2, 'Mettre les pâtes, les légumes, l''ail, le cube émietté et l''eau dans une grande casserole : les pâtes doivent être couvertes de liquide.'),
  ('one-pot-pasta-legumes', 3, 'Porter à ébullition à feu vif, puis cuire 12 minutes à feu moyen en remuant souvent pour que les pâtes n''attachent pas.'),
  ('one-pot-pasta-legumes', 4, 'Quand il ne reste presque plus de liquide et que les pâtes sont tendres, retirer du feu. Goûter et saler si besoin.'),
  ('one-pot-pasta-legumes', 5, 'Ajouter le basilic ciselé et le parmesan râpé, mélanger et servir.'),
  ('paella-poulet-chorizo', 1, 'Émincer l''oignon et l''ail, couper les poivrons en lanières. Dissoudre les cubes dans l''eau chaude.'),
  ('paella-poulet-chorizo', 2, 'Chauffer l''huile dans une grande poêle ou une sauteuse à feu moyen-vif. Dorer les cuisses 8 à 10 minutes en les retournant, puis ajouter le chorizo 2 minutes. Réserver le tout.'),
  ('paella-poulet-chorizo', 3, 'Dans la même poêle, faire revenir l''oignon, l''ail et les poivrons 5 minutes à feu moyen.'),
  ('paella-poulet-chorizo', 4, 'Ajouter le riz et remuer 2 minutes pour l''enrober de matière grasse, puis le curcuma et le paprika.'),
  ('paella-poulet-chorizo', 5, 'Verser le bouillon, remettre le poulet et le chorizo et répartir le riz uniformément. Cuire 20 minutes à feu moyen-doux sans remuer.'),
  ('paella-poulet-chorizo', 6, 'Enfoncer les crevettes et les petits pois dans le riz et cuire encore 10 minutes, jusqu''à ce que le liquide soit absorbé et les crevettes roses. Couvrir et laisser reposer 5 minutes, puis servir avec des quartiers de citron.'),
  ('pancakes', 1, 'Dans un saladier, mélanger la farine, le sucre et la levure.'),
  ('pancakes', 2, 'Ajouter les œufs et mélanger, puis verser le lait petit à petit en fouettant et terminer par le beurre fondu. La pâte doit être épaisse et lisse ; la laisser reposer 10 minutes.'),
  ('pancakes', 3, 'Chauffer une poêle à feu moyen et la graisser très légèrement. Verser une petite louche de pâte par pancake.'),
  ('pancakes', 4, 'Cuire 1 à 2 minutes, jusqu''à ce que des bulles apparaissent à la surface, retourner et cuire encore 1 minute, jusqu''à ce que les deux faces soient dorées.'),
  ('pancakes', 5, 'Servir chaud avec le sirop d''érable.'),
  ('papillotes-saumon-legumes', 1, 'Préchauffer le four à 200 °C. Couper la courgette et les carottes en julienne. Couper le citron en rondelles.'),
  ('papillotes-saumon-legumes', 2, 'Si vous servez du riz, le cuire dans une casserole d''eau bouillante 11 à 12 minutes.'),
  ('papillotes-saumon-legumes', 3, 'Répartir les légumes au centre de 4 grandes feuilles de papier cuisson. Poser un pavé de saumon sur chaque lit de légumes, ajouter une rondelle de citron, le thym, un filet d''huile, du sel et du poivre.'),
  ('papillotes-saumon-legumes', 4, 'Refermer les papillotes en repliant les bords plusieurs fois pour qu''elles soient bien étanches, et les poser sur la plaque du four.'),
  ('papillotes-saumon-legumes', 5, 'Enfourner 18 minutes : la chair du saumon doit être rosée et s''effeuiller facilement. Ouvrir les papillotes à table et servir avec le riz.'),
  ('patates-douces-feta-pois-chiches', 1, 'Préchauffer le four à 200 °C. Éplucher les patates douces et les couper en cubes d''environ 2 cm. Rincer, égoutter et sécher les pois chiches.'),
  ('patates-douces-feta-pois-chiches', 2, 'Sur la plaque du four, mélanger les patates douces et les pois chiches avec l''huile, le cumin, le paprika et le sel, en une seule couche.'),
  ('patates-douces-feta-pois-chiches', 3, 'Rôtir 35 minutes en remuant à mi-cuisson, jusqu''à ce que les patates douces soient tendres et caramélisées sur les bords.'),
  ('patates-douces-feta-pois-chiches', 4, 'Parsemer de feta émiettée, arroser de jus de citron et ajouter le persil ciselé au moment de servir.'),
  ('pates-thon-tomate', 1, 'Porter une grande casserole d''eau à ébullition, saler et cuire les pâtes 9 à 11 minutes (voir le paquet).'),
  ('pates-thon-tomate', 2, 'Pendant ce temps, émincer l''ail et le faire revenir 1 minute dans l''huile, dans une poêle à feu moyen, sans le laisser brunir.'),
  ('pates-thon-tomate', 3, 'Verser le coulis et laisser mijoter 10 minutes à feu doux. Saler et poivrer.'),
  ('pates-thon-tomate', 4, 'Ajouter le thon émietté, les olives et les câpres et réchauffer 2 minutes.'),
  ('pates-thon-tomate', 5, 'Égoutter les pâtes et les mélanger à la sauce.'),
  ('pates-tomate-basilic', 1, 'Chauffer l''huile dans une casserole à feu moyen et faire fondre l''oignon haché 5 minutes, jusqu''à ce qu''il soit translucide. Ajouter l''ail écrasé 1 minute.'),
  ('pates-tomate-basilic', 2, 'Verser le coulis, saler, poivrer et laisser mijoter 15 minutes à feu doux, à demi couvert.'),
  ('pates-tomate-basilic', 3, 'Pendant ce temps, cuire les pâtes dans une grande casserole d''eau bouillante salée 9 à 11 minutes (voir le paquet).'),
  ('pates-tomate-basilic', 4, 'Égoutter les pâtes, les mélanger à la sauce, puis ajouter le basilic ciselé et le parmesan râpé.'),
  ('penne-arrabbiata', 1, 'Dans une poêle, chauffer l''huile à feu doux avec l''ail émincé et le piment 2 minutes, sans les laisser colorer.'),
  ('penne-arrabbiata', 2, 'Ajouter les tomates, saler et laisser réduire 15 minutes à feu moyen-doux, jusqu''à ce que la sauce épaississe.'),
  ('penne-arrabbiata', 3, 'Pendant ce temps, cuire les penne dans une grande casserole d''eau bouillante salée 10 à 12 minutes (voir le paquet), jusqu''à ce qu''elles soient al dente.'),
  ('penne-arrabbiata', 4, 'Égoutter les pâtes et les mélanger à la sauce 1 minute à feu moyen.'),
  ('penne-arrabbiata', 5, 'Parsemer de persil et de parmesan râpé.'),
  ('penne-courgettes-feta', 1, 'Porter une grande casserole d''eau à ébullition, saler et cuire les penne 10 à 12 minutes (voir le paquet).'),
  ('penne-courgettes-feta', 2, 'Pendant ce temps, chauffer l''huile dans une grande poêle à feu moyen-vif et faire dorer les courgettes 8 minutes en remuant de temps en temps. Saler et poivrer.'),
  ('penne-courgettes-feta', 3, 'Prélever le zeste du citron et le presser.'),
  ('penne-courgettes-feta', 4, 'Égoutter les pâtes, les mélanger aux courgettes avec le zeste et le jus de citron.'),
  ('penne-courgettes-feta', 5, 'Ajouter la feta émiettée et la menthe ciselée au moment de servir.'),
  ('poelee-saucisses-lentilles', 1, 'Rincer les lentilles. Émincer l''oignon et couper les carottes en rondelles.'),
  ('poelee-saucisses-lentilles', 2, 'Dans une cocotte à feu moyen, faire dorer les saucisses 5 minutes en les retournant. Les réserver.'),
  ('poelee-saucisses-lentilles', 3, 'Dans la même cocotte, faire revenir l''oignon et les carottes 5 minutes dans la graisse des saucisses.'),
  ('poelee-saucisses-lentilles', 4, 'Ajouter les lentilles, le thym, le laurier et l''eau, puis remettre les saucisses. Porter à ébullition.'),
  ('poelee-saucisses-lentilles', 5, 'Cuire 30 minutes à frémissement, à demi couvert, jusqu''à ce que les lentilles soient tendres. Servir avec un peu de moutarde.'),
  ('pommes-de-terre-farcies', 1, 'Préchauffer le four à 200 °C. Laver les pommes de terre, les piquer à la fourchette et les cuire entières 40 minutes sur la plaque du four : la pointe d''un couteau doit s''y enfoncer facilement.'),
  ('pommes-de-terre-farcies', 2, 'Pendant ce temps, émincer l''oignon et le faire fondre 5 minutes dans une poêle à feu doux. Couper le jambon en petits dés.'),
  ('pommes-de-terre-farcies', 3, 'Couper les pommes de terre en deux dans la longueur et retirer la chair avec une cuillère, en laissant une fine épaisseur contre la peau.'),
  ('pommes-de-terre-farcies', 4, 'Écraser la chair avec la crème, le jambon et l''oignon ; saler et poivrer.'),
  ('pommes-de-terre-farcies', 5, 'Remplir les peaux, couvrir d''emmental et remettre au four 15 minutes, jusqu''à ce que le fromage soit doré.'),
  ('pommes-de-terre-oeufs-plat', 1, 'Éplucher les pommes de terre et les couper en dés d''environ 1,5 cm ; les sécher dans un torchon. Émincer l''oignon.'),
  ('pommes-de-terre-oeufs-plat', 2, 'Chauffer les deux tiers de l''huile dans une grande poêle à feu moyen-vif. Faire sauter les pommes de terre 20 minutes en remuant régulièrement, et ajouter l''oignon à mi-cuisson. Saler.'),
  ('pommes-de-terre-oeufs-plat', 3, 'En fin de cuisson, chauffer le reste d''huile dans une autre poêle à feu moyen et y casser les œufs. Cuire 3 à 4 minutes, jusqu''à ce que le blanc soit pris et le jaune encore coulant.'),
  ('pommes-de-terre-oeufs-plat', 4, 'Servir les pommes de terre surmontées des œufs, parsemées de persil, avec la salade.'),
  ('porc-caramel', 1, 'Émincer les oignons, hacher l''ail et râper le gingembre. Lancer le riz dans une casserole d''eau bouillante 10 à 12 minutes.'),
  ('porc-caramel', 2, 'Chauffer l''huile dans une sauteuse à feu vif et dorer le porc 5 minutes en remuant. Réserver.'),
  ('porc-caramel', 3, 'Baisser à feu moyen, ajouter le sucre et le laisser fondre sans remuer, en secouant la sauteuse, jusqu''à obtenir un caramel blond. Ajouter aussitôt les oignons, l''ail et le gingembre et remuer 2 minutes.'),
  ('porc-caramel', 4, 'Remettre le porc, ajouter la sauce soja et l''eau. Laisser mijoter 25 minutes à feu doux, à découvert, en remuant de temps en temps, jusqu''à ce que la sauce soit sirupeuse et nappe la viande.'),
  ('porc-caramel', 5, 'Servir avec le riz thaï.'),
  ('porc-moutarde', 1, 'Émincer les échalotes. Si vous servez des pâtes, les cuire dans une grande casserole d''eau bouillante en fin de recette.'),
  ('porc-moutarde', 2, 'Faire fondre le beurre dans une cocotte à feu moyen-vif et dorer le filet mignon entier 6 à 8 minutes en le tournant, jusqu''à ce qu''il soit coloré sur toutes les faces.'),
  ('porc-moutarde', 3, 'Ajouter les échalotes 2 minutes, puis verser le vin blanc en grattant le fond pour décoller les sucs.'),
  ('porc-moutarde', 4, 'Couvrir et cuire 20 minutes à feu doux, en retournant la viande à mi-cuisson.'),
  ('porc-moutarde', 5, 'Retirer la viande, ajouter la crème et la moutarde dans la cocotte et laisser réduire 5 minutes, jusqu''à ce que la sauce nappe. Trancher le filet en médaillons et napper de sauce.'),
  ('potee-chou-saucisses', 1, 'Couper le chou en quartiers en retirant le cœur dur. Le plonger 5 minutes dans un faitout d''eau bouillante, puis l''égoutter.'),
  ('potee-chou-saucisses', 2, 'Éplucher et émincer les oignons ; éplucher les carottes et les couper en tronçons ; éplucher les pommes de terre et les couper en deux si elles sont grosses.'),
  ('potee-chou-saucisses', 3, 'Dans le faitout vidé, faire revenir les lardons et les oignons 5 minutes à feu moyen.'),
  ('potee-chou-saucisses', 4, 'Ajouter le chou, les carottes, le laurier, l''eau et les cubes émiettés. Porter à ébullition, puis couvrir et cuire 40 minutes à feu doux.'),
  ('potee-chou-saucisses', 5, 'Ajouter les pommes de terre et les saucisses et cuire encore 30 minutes, jusqu''à ce que les pommes de terre soient tendres. Poivrer et servir avec un peu de bouillon.'),
  ('poulet-basquaise', 1, 'Émincer les oignons et l''ail ; couper les poivrons en lanières et les tomates en morceaux.'),
  ('poulet-basquaise', 2, 'Chauffer l''huile dans une cocotte à feu moyen-vif et dorer les cuisses 5 minutes par face, côté peau en premier. Réserver.'),
  ('poulet-basquaise', 3, 'Dans la même cocotte, faire revenir les oignons, les poivrons et l''ail 10 minutes à feu moyen, jusqu''à ce qu''ils soient tendres.'),
  ('poulet-basquaise', 4, 'Ajouter les tomates, le paprika et le thym, saler, poivrer, puis remettre le poulet.'),
  ('poulet-basquaise', 5, 'Couvrir et laisser mijoter 35 minutes à feu doux : la chair doit se détacher facilement de l''os.'),
  ('poulet-basquaise', 6, 'Pendant ce temps, cuire le riz dans une casserole d''eau bouillante 11 à 12 minutes. Servir le poulet et sa sauce avec le riz.'),
  ('poulet-citron-olives', 1, 'Émincer les oignons et l''ail, râper le gingembre. Presser un citron et couper l''autre en quartiers.'),
  ('poulet-citron-olives', 2, 'Chauffer l''huile dans une cocotte à feu moyen-vif et dorer les cuisses 5 minutes par face. Réserver.'),
  ('poulet-citron-olives', 3, 'Baisser à feu moyen et faire revenir les oignons, l''ail, le gingembre, le cumin et le curcuma 5 minutes.'),
  ('poulet-citron-olives', 4, 'Remettre le poulet, ajouter l''eau, le cube émietté, le jus du citron et les quartiers de l''autre. Couvrir et laisser mijoter 25 minutes à feu doux.'),
  ('poulet-citron-olives', 5, 'Ajouter les olives et cuire encore 10 minutes à découvert, pour que la sauce réduise un peu.'),
  ('poulet-citron-olives', 6, 'Préparer la semoule : la couvrir du même volume d''eau bouillante, couvrir 5 minutes puis l''égrener à la fourchette. Servir avec le poulet, parsemé de coriandre.'),
  ('poulet-curry-coco', 1, 'Émincer l''oignon et couper le poivron en lanières. Lancer le riz dans une casserole d''eau bouillante 11 à 12 minutes.'),
  ('poulet-curry-coco', 2, 'Chauffer l''huile dans une sauteuse à feu moyen et faire revenir l''oignon et le poivron 5 minutes.'),
  ('poulet-curry-coco', 3, 'Monter le feu, ajouter le poulet et le faire dorer 5 minutes, puis ajouter la pâte de curry et remuer 1 minute.'),
  ('poulet-curry-coco', 4, 'Verser le lait de coco, porter à frémissement et laisser mijoter 15 minutes à feu doux, jusqu''à ce que le poulet soit cuit à cœur et la sauce légèrement épaissie.'),
  ('poulet-curry-coco', 5, 'Servir avec le riz et la coriandre ciselée.'),
  ('poulet-grenailles-thym', 1, 'Préchauffer le four à 200 °C. Laver les grenailles sans les éplucher et les couper en deux si elles sont grosses.'),
  ('poulet-grenailles-thym', 2, 'Dans un grand plat allant au four, mélanger les grenailles avec l''huile, les gousses d''ail non épluchées, le thym, du sel et du poivre.'),
  ('poulet-grenailles-thym', 3, 'Poser les cuisses par-dessus, peau vers le haut, saler, poivrer, et glisser les quartiers de citron entre les morceaux.'),
  ('poulet-grenailles-thym', 4, 'Rôtir 45 minutes en remuant les pommes de terre à mi-cuisson : la peau du poulet doit être dorée et croustillante, et le jus qui s''écoule de la cuisse piquée doit être clair.'),
  ('poulet-miel-soja', 1, 'Cuire le riz dans une casserole d''eau bouillante 10 à 12 minutes. Cuire le brocoli en bouquets 6 minutes à la vapeur.'),
  ('poulet-miel-soja', 2, 'Hacher l''ail et râper le gingembre. Mélanger la sauce soja et le miel.'),
  ('poulet-miel-soja', 3, 'Chauffer l''huile dans une poêle à feu moyen-vif et dorer le poulet 8 minutes en remuant, jusqu''à ce qu''il soit cuit à cœur.'),
  ('poulet-miel-soja', 4, 'Ajouter l''ail et le gingembre 30 secondes, puis le mélange soja-miel. Laisser laquer 3 minutes en remuant, jusqu''à ce que la sauce devienne sirupeuse et brillante.'),
  ('poulet-miel-soja', 5, 'Parsemer de sésame et servir avec le riz et le brocoli.'),
  ('poulet-roti-legumes', 1, 'Préchauffer le four à 200 °C. Couper les pommes de terre en quartiers, les carottes en bâtonnets et les oignons rouges en quartiers.'),
  ('poulet-roti-legumes', 2, 'Dans un grand plat allant au four, mélanger les légumes et les gousses d''ail non épluchées avec l''huile, les herbes, du sel et du poivre, en une couche régulière.'),
  ('poulet-roti-legumes', 3, 'Poser les cuisses par-dessus, peau vers le haut, et les assaisonner.'),
  ('poulet-roti-legumes', 4, 'Enfourner 50 minutes en retournant les légumes à mi-cuisson : la peau doit être dorée et le jus qui s''écoule de la cuisse piquée doit être clair.'),
  ('poulet-yaourt-epices-basmati', 1, 'Hacher l''ail et râper le gingembre. Dans un saladier, mélanger le poulet avec le yaourt, le curry, le curcuma, le gingembre, l''ail et le sel. Laisser mariner au moins 15 minutes.'),
  ('poulet-yaourt-epices-basmati', 2, 'Rincer le riz basmati jusqu''à ce que l''eau soit claire, puis le cuire dans une casserole d''eau bouillante 10 à 11 minutes et l''égoutter.'),
  ('poulet-yaourt-epices-basmati', 3, 'Émincer l''oignon. Chauffer l''huile dans une poêle à feu moyen et faire revenir l''oignon 5 minutes.'),
  ('poulet-yaourt-epices-basmati', 4, 'Ajouter le poulet et sa marinade et cuire 12 minutes à feu moyen en remuant, jusqu''à ce que le poulet soit cuit à cœur et la sauce épaissie.'),
  ('poulet-yaourt-epices-basmati', 5, 'Servir avec le riz et la coriandre ciselée.'),
  ('puree-saucisses', 1, 'Éplucher les pommes de terre et les couper en morceaux égaux. Les mettre dans une casserole d''eau froide salée, porter à ébullition et cuire 20 minutes, jusqu''à ce que la pointe d''un couteau s''y enfonce sans résistance.'),
  ('puree-saucisses', 2, 'Pendant ce temps, cuire les saucisses 15 minutes dans une poêle à feu moyen en les retournant régulièrement, avec l''oignon émincé si vous l''utilisez.'),
  ('puree-saucisses', 3, 'Faire chauffer le lait. Égoutter les pommes de terre et les écraser au presse-purée avec le beurre.'),
  ('puree-saucisses', 4, 'Incorporer le lait chaud petit à petit jusqu''à la texture souhaitée, ajouter la muscade et saler. Servir avec les saucisses.'),
  ('quiche-lardons', 1, 'Préchauffer le four à 180 °C. Étaler la pâte dans un moule à tarte en gardant le papier de cuisson, et piquer le fond à la fourchette.'),
  ('quiche-lardons', 2, 'Dans une poêle à feu moyen, faire dorer les lardons à sec 5 minutes, puis les égoutter sur une assiette et les répartir sur la pâte.'),
  ('quiche-lardons', 3, 'Battre les œufs avec la crème, le lait, la muscade et le poivre.'),
  ('quiche-lardons', 4, 'Verser l''appareil sur les lardons et parsemer d''emmental.'),
  ('quiche-lardons', 5, 'Enfourner 35 minutes, jusqu''à ce que l''appareil soit pris et doré. Il doit à peine trembler au centre. Laisser reposer 5 minutes avant de couper.'),
  ('quiche-thon-tomate', 1, 'Préchauffer le four à 190 °C. Étaler la pâte dans un moule à tarte en gardant le papier de cuisson, piquer le fond à la fourchette et le badigeonner de moutarde.'),
  ('quiche-thon-tomate', 2, 'Égoutter et émietter le thon, le répartir sur la pâte, puis disposer les rondelles de tomate par-dessus.'),
  ('quiche-thon-tomate', 3, 'Battre les œufs avec la crème, le lait et l''emmental ; saler, poivrer et verser sur la garniture.'),
  ('quiche-thon-tomate', 4, 'Enfourner 35 minutes, jusqu''à ce que l''appareil soit pris et doré. Laisser reposer 5 minutes avant de couper.'),
  ('ratatouille', 1, 'Couper l''aubergine, les courgettes, les poivrons et les tomates en dés d''environ 2 cm. Émincer les oignons et hacher l''ail.'),
  ('ratatouille', 2, 'Chauffer un peu d''huile dans une cocotte à feu moyen-vif et faire dorer l''aubergine 8 minutes en remuant. Réserver, puis faire de même avec les courgettes 5 minutes, et les poivrons 5 minutes, en ajoutant un peu d''huile à chaque fois.'),
  ('ratatouille', 3, 'Dans la même cocotte, faire fondre les oignons 5 minutes avec le reste d''huile, ajouter l''ail 1 minute, puis les tomates.'),
  ('ratatouille', 4, 'Remettre tous les légumes, ajouter les herbes, saler et poivrer.'),
  ('ratatouille', 5, 'Couvrir et laisser mijoter 30 minutes à feu doux en remuant délicatement de temps en temps, jusqu''à ce que les légumes soient fondants mais encore entiers.'),
  ('rigatoni-saucisse-tomate', 1, 'Émincer l''oignon et l''ail. Retirer la chair des saucisses de leur boyau.'),
  ('rigatoni-saucisse-tomate', 2, 'Chauffer l''huile dans une sauteuse à feu moyen et faire revenir l''oignon 4 minutes. Ajouter la chair de saucisse et la faire dorer 6 minutes en l''émiettant à la cuillère en bois.'),
  ('rigatoni-saucisse-tomate', 3, 'Ajouter l''ail 1 minute, puis les tomates. Saler, poivrer et laisser mijoter 15 minutes à feu doux.'),
  ('rigatoni-saucisse-tomate', 4, 'Pendant ce temps, cuire les rigatoni dans une grande casserole d''eau bouillante salée 11 à 13 minutes (voir le paquet).'),
  ('rigatoni-saucisse-tomate', 5, 'Égoutter les pâtes, les mélanger à la sauce et servir avec le parmesan râpé.'),
  ('risotto-butternut', 1, 'Dissoudre les cubes dans l''eau chaude et garder ce bouillon frémissant dans une casserole à feu doux. Émincer finement l''oignon.'),
  ('risotto-butternut', 2, 'Dans une sauteuse à fond épais, faire fondre l''oignon dans la moitié du beurre 3 minutes à feu moyen. Ajouter la courge et cuire 3 minutes.'),
  ('risotto-butternut', 3, 'Ajouter le riz et le nacrer 2 minutes en remuant, jusqu''à ce que les grains deviennent translucides sur les bords.'),
  ('risotto-butternut', 4, 'Verser le vin et laisser évaporer. Ajouter ensuite le bouillon louche par louche, en remuant souvent et en attendant que chaque louche soit presque absorbée, pendant 18 à 20 minutes.'),
  ('risotto-butternut', 5, 'Le riz doit être tendre mais encore légèrement ferme au centre, et le risotto crémeux. Hors du feu, ajouter le reste du beurre et le parmesan, couvrir 2 minutes, saler si besoin et servir.'),
  ('risotto-champignons', 1, 'Dissoudre le cube dans l''eau et garder ce bouillon frémissant dans une casserole à feu doux.'),
  ('risotto-champignons', 2, 'Dans une sauteuse, faire dorer les champignons dans la moitié du beurre 5 minutes à feu vif, jusqu''à ce que leur eau soit évaporée. Réserver.'),
  ('risotto-champignons', 3, 'Dans la même sauteuse, faire suer l''oignon haché dans l''huile 3 minutes à feu moyen. Ajouter le riz et le nacrer 2 minutes en remuant.'),
  ('risotto-champignons', 4, 'Verser le vin blanc et laisser évaporer, puis ajouter le bouillon louche par louche en remuant souvent, pendant 18 minutes, en attendant que chaque louche soit presque absorbée.'),
  ('risotto-champignons', 5, 'Hors du feu, incorporer les champignons, le parmesan et le reste du beurre. Couvrir 2 minutes et servir : le risotto doit être crémeux et onctueux.'),
  ('risotto-petits-pois-jambon', 1, 'Dissoudre les cubes dans l''eau chaude et garder ce bouillon frémissant dans une casserole à feu doux. Émincer finement l''oignon.'),
  ('risotto-petits-pois-jambon', 2, 'Dans une sauteuse, faire fondre l''oignon dans la moitié du beurre 3 minutes à feu moyen. Ajouter le riz et le nacrer 2 minutes en remuant.'),
  ('risotto-petits-pois-jambon', 3, 'Ajouter le bouillon louche par louche en remuant souvent, pendant 18 minutes. Ajouter les petits pois avec les dernières louches, 4 à 5 minutes avant la fin.'),
  ('risotto-petits-pois-jambon', 4, 'Hors du feu, ajouter le jambon en lanières, le reste du beurre et le parmesan. Couvrir 2 minutes et servir aussitôt.'),
  ('riz-au-lait', 1, 'Dans une casserole à fond épais, porter le lait à ébullition avec la vanille, en surveillant pour qu''il ne déborde pas.'),
  ('riz-au-lait', 2, 'Ajouter le riz en pluie, baisser à feu très doux et cuire 40 minutes en remuant souvent, surtout vers la fin pour éviter qu''il attache. Le riz doit être fondant et le mélange crémeux.'),
  ('riz-au-lait', 3, 'Ajouter le sucre en fin de cuisson et remuer 2 minutes.'),
  ('riz-au-lait', 4, 'Verser dans un saladier ou des ramequins et laisser refroidir. Il épaissit en refroidissant ; servir tiède ou froid.'),
  ('riz-cantonais', 1, 'Si le riz n''est pas déjà cuit, le cuire dans une casserole d''eau bouillante 10 à 12 minutes, l''égoutter, l''étaler sur une assiette et le laisser refroidir complètement.'),
  ('riz-cantonais', 2, 'Battre les œufs. Chauffer un filet d''huile dans une poêle à feu moyen, verser les œufs et cuire une omelette fine 2 minutes. La rouler et la couper en lanières.'),
  ('riz-cantonais', 3, 'Émincer l''oignon. Chauffer le reste d''huile dans un wok ou une grande poêle à feu vif et faire revenir l''oignon 2 minutes, puis les petits pois et le jambon en dés 2 minutes.'),
  ('riz-cantonais', 4, 'Ajouter le riz froid et le faire sauter 3 minutes en remuant, en séparant bien les grains.'),
  ('riz-cantonais', 5, 'Ajouter la sauce soja et les lanières d''omelette et sauter encore 2 minutes.'),
  ('riz-haricots-rouges', 1, 'Cuire le riz dans une casserole d''eau bouillante 11 à 12 minutes et l''égoutter.'),
  ('riz-haricots-rouges', 2, 'Émincer l''oignon et couper le poivron en dés. Chauffer l''huile dans une sauteuse à feu moyen et les faire revenir 5 minutes. Ajouter le cumin et le paprika et remuer 1 minute.'),
  ('riz-haricots-rouges', 3, 'Ajouter les tomates et les haricots rincés, saler et laisser mijoter 10 minutes à feu doux.'),
  ('riz-haricots-rouges', 4, 'Mélanger avec le riz et parsemer de coriandre ciselée.'),
  ('riz-saute-legumes-oeuf', 1, 'Si le riz n''est pas déjà cuit, le cuire dans une casserole d''eau bouillante 10 à 12 minutes, l''égoutter, l''étaler et le laisser refroidir complètement.'),
  ('riz-saute-legumes-oeuf', 2, 'Chauffer l''huile dans un wok ou une grande poêle à feu vif et faire revenir l''oignon et les carottes 5 minutes.'),
  ('riz-saute-legumes-oeuf', 3, 'Ajouter les petits pois et le riz et faire sauter 3 minutes en séparant bien les grains.'),
  ('riz-saute-legumes-oeuf', 4, 'Pousser le riz sur le côté, casser les œufs dans l''espace libéré et les brouiller 1 à 2 minutes à la spatule, puis mélanger avec le riz.'),
  ('riz-saute-legumes-oeuf', 5, 'Assaisonner avec la sauce soja et parsemer de ciboulette.'),
  ('rougail-saucisses', 1, 'Émincer les oignons, hacher l''ail et râper le gingembre. Couper les saucisses en tronçons et les tomates en dés.'),
  ('rougail-saucisses', 2, 'Chauffer l''huile dans une cocotte à feu moyen-vif et faire dorer les saucisses 8 minutes en remuant. Retirer l''excédent de graisse si besoin.'),
  ('rougail-saucisses', 3, 'Ajouter les oignons, l''ail, le gingembre et le curcuma et faire revenir 5 minutes à feu moyen.'),
  ('rougail-saucisses', 4, 'Ajouter les tomates et le piment, couvrir et laisser mijoter 30 minutes à feu doux, en remuant de temps en temps, jusqu''à ce que les tomates soient fondues en sauce.'),
  ('rougail-saucisses', 5, 'Pendant ce temps, cuire le riz dans une casserole d''eau bouillante 11 à 12 minutes. Servir le rougail sur le riz.'),
  ('salade-boulgour-legumes-rotis', 1, 'Préchauffer le four à 200 °C. Couper l''aubergine, la courgette et le poivron en dés d''environ 2 cm.'),
  ('salade-boulgour-legumes-rotis', 2, 'Sur la plaque du four, mélanger les légumes avec 2 cuillères d''huile et une pincée de sel, en une seule couche. Rôtir 30 minutes en remuant à mi-cuisson, jusqu''à ce qu''ils soient tendres et dorés.'),
  ('salade-boulgour-legumes-rotis', 3, 'Pendant ce temps, cuire le boulgour 10 minutes à couvert dans une casserole avec deux fois son volume d''eau, puis l''égrener et le laisser tiédir.'),
  ('salade-boulgour-legumes-rotis', 4, 'Mélanger le boulgour avec les légumes rôtis, la feta émiettée, la menthe ciselée, le jus du citron et le reste d''huile. Saler si besoin.'),
  ('salade-cesar-poulet', 1, 'Couper le pain en cubes. Chauffer 1 cuillère d''huile dans une poêle à feu moyen avec la gousse d''ail écrasée et dorer les croûtons 4 à 5 minutes en remuant. Retirer l''ail.'),
  ('salade-cesar-poulet', 2, 'Dans la même poêle, chauffer le reste d''huile et cuire le poulet 8 à 10 minutes en le retournant à mi-cuisson, jusqu''à ce qu''il soit cuit à cœur. Le laisser reposer 2 minutes puis le trancher.'),
  ('salade-cesar-poulet', 3, 'Mélanger la mayonnaise avec le jus du citron et un peu de parmesan râpé.'),
  ('salade-cesar-poulet', 4, 'Laver et essorer la salade, la déchirer en morceaux dans un saladier. Ajouter le poulet, les croûtons et la sauce, mélanger et parsemer du reste de parmesan en copeaux.'),
  ('salade-chevre-chaud', 1, 'Préchauffer le four à 200 °C. Couper le fromage de chèvre en rondelles.'),
  ('salade-chevre-chaud', 2, 'Poser les tranches de pain sur la plaque du four, ajouter une rondelle de chèvre sur chacune et un filet de miel.'),
  ('salade-chevre-chaud', 3, 'Enfourner 8 minutes, jusqu''à ce que le chèvre soit fondant et légèrement doré.'),
  ('salade-chevre-chaud', 4, 'Pendant ce temps, laver et essorer la salade, puis l''assaisonner avec l''huile et le vinaigre balsamique. Ajouter les noix concassées.'),
  ('salade-chevre-chaud', 5, 'Répartir la salade dans les assiettes et poser les toasts chauds par-dessus.'),
  ('salade-grecque', 1, 'Couper les tomates en quartiers, le concombre en demi-rondelles épaisses et le poivron en lanières. Émincer finement l''oignon rouge.'),
  ('salade-grecque', 2, 'Réunir les légumes dans un saladier et ajouter les olives.'),
  ('salade-grecque', 3, 'Couper la feta en dés ou la poser en tranche sur le dessus.'),
  ('salade-grecque', 4, 'Arroser d''huile d''olive, parsemer d''herbes de Provence et servir avec le pain.'),
  ('salade-lentilles-feta', 1, 'Rincer les lentilles et les cuire 20 minutes dans une casserole d''eau froide, sans sel, portée à frémissement : elles doivent être tendres mais entières. Les égoutter.'),
  ('salade-lentilles-feta', 2, 'Dans un saladier, fouetter la moutarde avec le vinaigre, puis ajouter l''huile en fouettant.'),
  ('salade-lentilles-feta', 3, 'Couper les tomates cerises en deux et le concombre en dés. Les mélanger avec l''oignon et les lentilles encore tièdes, qui absorberont mieux la vinaigrette.'),
  ('salade-lentilles-feta', 4, 'Ajouter la feta, la vinaigrette et le persil ciselé, et mélanger délicatement.'),
  ('salade-nicoise', 1, 'Plonger les œufs dans une casserole d''eau bouillante et les cuire 10 minutes, puis les refroidir dans l''eau froide et les écaler.'),
  ('salade-nicoise', 2, 'Équeuter les haricots verts et les cuire 6 minutes dans une casserole d''eau bouillante salée ; les refroidir aussitôt à l''eau froide et les égoutter.'),
  ('salade-nicoise', 3, 'Préparer la vinaigrette en fouettant le vinaigre, une pincée de sel et l''huile.'),
  ('salade-nicoise', 4, 'Disposer la salade dans un grand saladier ou sur les assiettes, puis les tomates en quartiers, le thon égoutté, les œufs en quartiers, les haricots, les olives et l''oignon émincé.'),
  ('salade-nicoise', 5, 'Arroser de vinaigrette juste avant de servir.'),
  ('salade-pates-thon', 1, 'Cuire les pâtes dans une grande casserole d''eau bouillante 9 à 11 minutes (voir le paquet), les égoutter, les passer sous l''eau froide et bien les égoutter.'),
  ('salade-pates-thon', 2, 'Si vous ajoutez des œufs, les cuire 10 minutes dans l''eau bouillante, les refroidir et les écaler.'),
  ('salade-pates-thon', 3, 'Émietter le thon égoutté et couper les tomates cerises en deux. Égoutter le maïs.'),
  ('salade-pates-thon', 4, 'Fouetter le vinaigre et l''huile, et la mayonnaise si vous l''utilisez. Mélanger les pâtes, le thon, les tomates et le maïs avec cette sauce.'),
  ('salade-pates-thon', 5, 'Ajouter les œufs durs en quartiers au moment de servir.'),
  ('salade-piemontaise', 1, 'Mettre les pommes de terre non épluchées dans une casserole d''eau froide salée, porter à ébullition et cuire 20 minutes, jusqu''à ce qu''elles soient tendres. Les égoutter et les laisser refroidir.'),
  ('salade-piemontaise', 2, 'Cuire les œufs 10 minutes dans une casserole d''eau bouillante, les refroidir à l''eau froide et les écaler.'),
  ('salade-piemontaise', 3, 'Éplucher les pommes de terre et les couper en dés. Couper les œufs, le jambon, les tomates et les cornichons en dés.'),
  ('salade-piemontaise', 4, 'Mélanger la mayonnaise et la moutarde, puis tous les ingrédients. Parsemer de persil ciselé et réfrigérer jusqu''au service.'),
  ('salade-quinoa-avocat-mais', 1, 'Rincer le quinoa et le cuire 12 minutes dans une casserole d''eau bouillante, puis l''égoutter et le rincer à l''eau froide.'),
  ('salade-quinoa-avocat-mais', 2, 'Rincer et égoutter le maïs et les haricots. Couper les tomates cerises en deux et les avocats en dés.'),
  ('salade-quinoa-avocat-mais', 3, 'Dans un saladier, mélanger le quinoa avec le maïs, les haricots, les tomates et l''avocat.'),
  ('salade-quinoa-avocat-mais', 4, 'Assaisonner avec le jus des citrons verts, l''huile, la coriandre ciselée et le sel. Servir frais.'),
  ('salade-riz-thon', 1, 'Cuire le riz dans une casserole d''eau bouillante 11 à 12 minutes, l''égoutter, le rincer à l''eau froide et le laisser refroidir.'),
  ('salade-riz-thon', 2, 'Cuire les œufs 10 minutes dans une casserole d''eau bouillante, les refroidir à l''eau froide et les écaler.'),
  ('salade-riz-thon', 3, 'Couper les tomates, le poivron et les œufs en dés. Émietter le thon et égoutter le maïs.'),
  ('salade-riz-thon', 4, 'Dans un saladier, fouetter la moutarde et le vinaigre avec une pincée de sel, puis l''huile.'),
  ('salade-riz-thon', 5, 'Mélanger le riz, le thon, le maïs, les légumes, les œufs et les olives avec la vinaigrette. Réfrigérer jusqu''au service.'),
  ('saumon-grenailles-citron', 1, 'Préchauffer le four à 200 °C. Laver les grenailles sans les éplucher et les couper en deux.'),
  ('saumon-grenailles-citron', 2, 'Dans un plat allant au four, les mélanger avec l''huile, du sel et du poivre, face coupée vers le bas. Rôtir 25 minutes, jusqu''à ce qu''elles soient dorées.'),
  ('saumon-grenailles-citron', 3, 'Poser les pavés de saumon parmi les pommes de terre, les arroser du jus de la moitié du citron, saler et poivrer.'),
  ('saumon-grenailles-citron', 4, 'Remettre au four 12 minutes : le saumon doit être rosé au centre et s''effeuiller facilement.'),
  ('saumon-grenailles-citron', 5, 'Parsemer de ciboulette ciselée et servir avec le reste du citron en quartiers.'),
  ('saumon-riz-brocoli', 1, 'Préchauffer le four à 200 °C. Cuire le riz dans une casserole d''eau bouillante 11 à 12 minutes et l''égoutter.'),
  ('saumon-riz-brocoli', 2, 'Disposer les pavés de saumon dans un plat allant au four, les arroser d''huile et du jus de la moitié du citron.'),
  ('saumon-riz-brocoli', 3, 'Enfourner 15 minutes : la chair doit être rosée au centre et s''effeuiller facilement.'),
  ('saumon-riz-brocoli', 4, 'Pendant ce temps, cuire le brocoli 6 minutes à la vapeur : il doit rester vert vif et légèrement croquant.'),
  ('saumon-riz-brocoli', 5, 'Servir le saumon avec le riz, le brocoli et le reste du citron en quartiers.'),
  ('shakshuka', 1, 'Émincer l''oignon et l''ail, couper les poivrons en lanières.'),
  ('shakshuka', 2, 'Chauffer l''huile dans une grande poêle à feu moyen et faire revenir l''oignon, les poivrons et l''ail 8 minutes, jusqu''à ce qu''ils soient tendres.'),
  ('shakshuka', 3, 'Ajouter le cumin et le paprika et remuer 1 minute, puis verser les tomates. Saler et laisser réduire 10 minutes à feu moyen-doux, jusqu''à ce que la sauce épaississe.'),
  ('shakshuka', 4, 'Creuser des puits dans la sauce avec une cuillère et y casser les œufs. Couvrir et cuire 6 à 8 minutes à feu doux, jusqu''à ce que les blancs soient pris et les jaunes encore coulants.'),
  ('shakshuka', 5, 'Parsemer de coriandre ciselée et servir dans la poêle, avec le pain.'),
  ('soupe-legumes-hiver', 1, 'Éplucher et émincer l''oignon ; émincer le poireau et bien le rincer. Éplucher et couper en dés les pommes de terre, les carottes et le navet.'),
  ('soupe-legumes-hiver', 2, 'Dans un faitout à feu moyen, faire suer l''oignon et le poireau 5 minutes avec un petit filet d''eau, à couvert, sans coloration.'),
  ('soupe-legumes-hiver', 3, 'Ajouter les autres légumes, le cube émietté et l''eau. Porter à ébullition.'),
  ('soupe-legumes-hiver', 4, 'Cuire 30 minutes à frémissement, jusqu''à ce que les légumes s''écrasent facilement à la fourchette.'),
  ('soupe-legumes-hiver', 5, 'Mixer jusqu''à obtenir une soupe lisse, ajouter la crème, saler, poivrer et servir chaud.'),
  ('soupe-lentilles-corail-carottes', 1, 'Émincer l''oignon, éplucher les carottes et les couper en rondelles fines. Rincer les lentilles jusqu''à ce que l''eau soit claire.'),
  ('soupe-lentilles-corail-carottes', 2, 'Chauffer l''huile dans un faitout à feu moyen et faire revenir l''oignon avec le cumin 3 minutes.'),
  ('soupe-lentilles-corail-carottes', 3, 'Ajouter les carottes, les lentilles, l''eau et le cube émietté. Porter à ébullition puis cuire 20 minutes à frémissement, jusqu''à ce que les carottes soient tendres et les lentilles défaites.'),
  ('soupe-lentilles-corail-carottes', 4, 'Ajouter le lait de coco et mixer jusqu''à obtenir une soupe lisse. Saler et servir chaud.'),
  ('soupe-miso-legumes', 1, 'Émincer finement les champignons, éplucher la carotte et la couper en fines rondelles ou en julienne. Râper le gingembre et couper le tofu en cubes.'),
  ('soupe-miso-legumes', 2, 'Dans une casserole, porter l''eau à ébullition avec le cube émietté, le gingembre et la sauce soja.'),
  ('soupe-miso-legumes', 3, 'Ajouter les champignons et la carotte et cuire 5 minutes à frémissement.'),
  ('soupe-miso-legumes', 4, 'Ajouter les nouilles et le tofu et cuire 4 minutes, jusqu''à ce que les nouilles soient souples.'),
  ('soupe-miso-legumes', 5, 'Hors du feu, ajouter les épinards : ils tombent en 1 minute dans le bouillon chaud. Servir aussitôt dans des bols.'),
  ('soupe-oignon-gratinee', 1, 'Dans un faitout, faire fondre le beurre à feu doux et ajouter les oignons émincés. Les cuire 25 minutes en remuant régulièrement, jusqu''à ce qu''ils soient fondants et bien dorés, sans brûler.'),
  ('soupe-oignon-gratinee', 2, 'Saupoudrer de farine et remuer 1 minute. Verser le vin et laisser bouillir 1 minute, puis ajouter l''eau et les cubes émiettés.'),
  ('soupe-oignon-gratinee', 3, 'Cuire 20 minutes à frémissement. Poivrer.'),
  ('soupe-oignon-gratinee', 4, 'Allumer le gril du four. Faire griller les tranches de pain.'),
  ('soupe-oignon-gratinee', 5, 'Répartir la soupe dans des bols allant au four, couvrir de pain grillé puis d''emmental.'),
  ('soupe-oignon-gratinee', 6, 'Passer 5 minutes sous le gril du four, jusqu''à ce que le fromage soit doré et bouillonnant. Servir aussitôt.'),
  ('soupe-potiron', 1, 'Éplucher et émincer l''oignon ; éplucher le potiron et la pomme de terre et les couper en cubes.'),
  ('soupe-potiron', 2, 'Dans un faitout à feu moyen, faire suer l''oignon 3 minutes avec un petit filet d''eau, sans coloration.'),
  ('soupe-potiron', 3, 'Ajouter le potiron, la pomme de terre, le cube émietté et l''eau. Porter à ébullition puis cuire 25 minutes à frémissement, jusqu''à ce que les légumes s''écrasent à la fourchette.'),
  ('soupe-potiron', 4, 'Mixer finement jusqu''à obtenir un velouté lisse.'),
  ('soupe-potiron', 5, 'Ajouter la crème et la muscade, saler et servir chaud.'),
  ('soupe-thai-poulet-coco', 1, 'Émincer finement les champignons. Couper le poulet en fines lanières si ce n''est pas déjà fait.'),
  ('soupe-thai-poulet-coco', 2, 'Dans une casserole à feu moyen, faire chauffer la pâte de curry 1 minute en remuant, jusqu''à ce qu''elle embaume.'),
  ('soupe-thai-poulet-coco', 3, 'Ajouter le lait de coco, l''eau et le cube émietté. Porter à frémissement.'),
  ('soupe-thai-poulet-coco', 4, 'Ajouter le poulet et les champignons et cuire 10 minutes à frémissement, jusqu''à ce que le poulet soit cuit à cœur.'),
  ('soupe-thai-poulet-coco', 5, 'Ajouter les nouilles de riz et cuire 4 minutes, jusqu''à ce qu''elles soient souples.'),
  ('soupe-thai-poulet-coco', 6, 'Hors du feu, ajouter le jus du citron vert et la coriandre ciselée. Servir aussitôt.'),
  ('soupe-tomate-pois-chiches', 1, 'Émincer l''oignon et l''ail, éplucher les carottes et les couper en petits dés.'),
  ('soupe-tomate-pois-chiches', 2, 'Chauffer l''huile dans un faitout à feu moyen et faire revenir l''oignon, les carottes et l''ail 5 minutes.'),
  ('soupe-tomate-pois-chiches', 3, 'Ajouter le cumin et le paprika et remuer 1 minute, puis les tomates, le cube émietté et l''eau.'),
  ('soupe-tomate-pois-chiches', 4, 'Cuire 20 minutes à frémissement, jusqu''à ce que les carottes soient tendres. Mixer à moitié pour garder des morceaux.'),
  ('soupe-tomate-pois-chiches', 5, 'Ajouter les pois chiches rincés et réchauffer 5 minutes à feu doux avant de servir.'),
  ('spaghetti-aglio-olio', 1, 'Porter une grande casserole d''eau à ébullition, saler et cuire les spaghetti 9 à 11 minutes (voir le paquet). Ciseler le persil.'),
  ('spaghetti-aglio-olio', 2, 'Pendant ce temps, mettre l''huile, l''ail en lamelles et le piment dans une grande poêle froide. Chauffer à feu doux 3 à 4 minutes, jusqu''à ce que l''ail blondisse à peine : s''il brunit, il devient amer.'),
  ('spaghetti-aglio-olio', 3, 'Prélever une petite louche d''eau de cuisson, puis égoutter les pâtes.'),
  ('spaghetti-aglio-olio', 4, 'Verser les pâtes dans la poêle avec l''eau de cuisson et mélanger 1 minute à feu moyen, jusqu''à ce que la sauce enrobe les spaghetti.'),
  ('spaghetti-aglio-olio', 5, 'Ajouter le persil et servir avec le parmesan.'),
  ('spaghetti-carbonara', 1, 'Porter une grande casserole d''eau à ébullition, saler et cuire les spaghetti 9 à 11 minutes (voir le paquet).'),
  ('spaghetti-carbonara', 2, 'Pendant ce temps, faire dorer les lardons à sec 5 minutes dans une grande poêle à feu moyen, jusqu''à ce qu''ils soient croustillants. Retirer du feu.'),
  ('spaghetti-carbonara', 3, 'Dans un bol, battre l''œuf entier et les jaunes avec le parmesan et beaucoup de poivre.'),
  ('spaghetti-carbonara', 4, 'Prélever une louche d''eau de cuisson, puis égoutter les pâtes et les verser dans la poêle avec les lardons, hors du feu. Mélanger.'),
  ('spaghetti-carbonara', 5, 'Ajouter le mélange aux œufs et un peu d''eau de cuisson en remuant vivement pendant 1 minute : la chaleur des pâtes doit épaissir la sauce sans cuire les œufs en omelette. Servir aussitôt.'),
  ('steak-hache-frites-four', 1, 'Préchauffer le four à 220 °C. Éplucher les pommes de terre et les couper en frites d''environ 1 cm. Les rincer et bien les sécher dans un torchon.'),
  ('steak-hache-frites-four', 2, 'Mélanger les frites avec l''huile et le sel et les étaler en une seule couche sur la plaque du four, sans qu''elles se chevauchent.'),
  ('steak-hache-frites-four', 3, 'Enfourner 35 minutes en les retournant à mi-cuisson, jusqu''à ce qu''elles soient dorées et croustillantes.'),
  ('steak-hache-frites-four', 4, 'Dix minutes avant la fin, chauffer une poêle à feu vif et cuire les steaks 2 à 4 minutes par face selon la cuisson souhaitée. Saler.'),
  ('steak-hache-frites-four', 5, 'Servir avec la salade et le ketchup.'),
  ('steak-haricots-verts', 1, 'Éplucher les pommes de terre et les couper en dés d''environ 1,5 cm. Chauffer l''huile dans une poêle à feu moyen-vif et les faire sauter 20 minutes en remuant régulièrement, jusqu''à ce qu''elles soient dorées et tendres.'),
  ('steak-haricots-verts', 2, 'Pendant ce temps, équeuter les haricots verts et les cuire 8 minutes dans une casserole d''eau bouillante. Les égoutter. Hacher l''ail et le persil.'),
  ('steak-haricots-verts', 3, 'Sortir les steaks du réfrigérateur 10 minutes avant. Faire fondre la moitié du beurre dans une autre poêle à feu vif et saisir les steaks 2 à 3 minutes par face selon la cuisson souhaitée. Les laisser reposer 2 minutes.'),
  ('steak-haricots-verts', 4, 'Dans la poêle des steaks, faire fondre le reste du beurre et faire sauter les haricots 2 minutes avec l''ail et le persil. Servir avec les pommes de terre.'),
  ('taboule', 1, 'Dans un saladier, mélanger la semoule avec le jus des citrons, l''huile et 20 cl d''eau froide. Laisser gonfler 15 minutes, puis l''égrener à la fourchette.'),
  ('taboule', 2, 'Pendant ce temps, couper les tomates, le concombre et l''oignon rouge en petits dés. Hacher finement le persil et la menthe.'),
  ('taboule', 3, 'Mélanger le tout avec la semoule et saler.'),
  ('taboule', 4, 'Réfrigérer au moins 30 minutes : la semoule finit d''absorber le jus des légumes. Égrener de nouveau avant de servir.'),
  ('tacos-poulet', 1, 'Mélanger le poulet avec le paprika, le cumin et la moitié de l''huile.'),
  ('tacos-poulet', 2, 'Chauffer le reste d''huile dans une poêle à feu vif. Saisir le poulet et le poivron 8 à 10 minutes en remuant, jusqu''à ce que le poulet soit doré et cuit à cœur.'),
  ('tacos-poulet', 3, 'Mélanger le fromage blanc avec le jus du citron vert.'),
  ('tacos-poulet', 4, 'Laver et essorer la salade, couper les tomates en dés.'),
  ('tacos-poulet', 5, 'Réchauffer les tortillas 20 secondes de chaque côté dans une poêle sèche. Les garnir de salade, de tomate, de poulet et de sauce, puis les rouler.'),
  ('tagliatelles-champignons-creme', 1, 'Porter une grande casserole d''eau à ébullition, saler et cuire les tagliatelles 6 à 8 minutes (voir le paquet).'),
  ('tagliatelles-champignons-creme', 2, 'Pendant ce temps, faire fondre le beurre dans une grande poêle à feu moyen et faire revenir l''échalote 2 minutes.'),
  ('tagliatelles-champignons-creme', 3, 'Monter à feu vif, ajouter les champignons et les faire dorer 6 à 8 minutes, jusqu''à ce que leur eau soit évaporée.'),
  ('tagliatelles-champignons-creme', 4, 'Ajouter l''ail 1 minute, puis la crème, et laisser réduire 3 minutes. Saler et poivrer.'),
  ('tagliatelles-champignons-creme', 5, 'Égoutter les tagliatelles en gardant un peu d''eau de cuisson, les mélanger à la sauce en la détendant si besoin, et servir avec le persil et le parmesan.'),
  ('tarte-fine-tomate-mozzarella', 1, 'Préchauffer le four à 200 °C. Dérouler la pâte sur la plaque du four avec son papier, la piquer à la fourchette et la tartiner de pesto en laissant un bord de 2 cm.'),
  ('tarte-fine-tomate-mozzarella', 2, 'Couper les tomates et la mozzarella en tranches et les laisser égoutter quelques minutes sur une assiette.'),
  ('tarte-fine-tomate-mozzarella', 3, 'Disposer les tomates et la mozzarella en les alternant, saler légèrement et arroser d''huile.'),
  ('tarte-fine-tomate-mozzarella', 4, 'Enfourner 25 minutes, jusqu''à ce que la pâte soit bien dorée et gonflée sur les bords.'),
  ('tarte-fine-tomate-mozzarella', 5, 'Parsemer de basilic au moment de servir.'),
  ('tarte-poireaux-chevre', 1, 'Préchauffer le four à 180 °C. Émincer les poireaux et bien les rincer.'),
  ('tarte-poireaux-chevre', 2, 'Faire fondre le beurre dans une poêle à feu doux, ajouter les poireaux et les faire fondre 15 minutes à couvert, en remuant de temps en temps, sans coloration.'),
  ('tarte-poireaux-chevre', 3, 'Étaler la pâte dans un moule à tarte en gardant le papier de cuisson, piquer le fond et y répartir les poireaux.'),
  ('tarte-poireaux-chevre', 4, 'Battre les œufs avec la crème et poivrer. Verser sur les poireaux, puis disposer le chèvre en rondelles.'),
  ('tarte-poireaux-chevre', 5, 'Enfourner 35 minutes, jusqu''à ce que l''appareil soit pris et doré. Laisser reposer 5 minutes avant de couper.'),
  ('tofu-croustillant-brocoli', 1, 'Cuire le riz dans une casserole d''eau bouillante 10 à 12 minutes. Hacher l''ail et râper le gingembre ; détailler le brocoli en petits bouquets.'),
  ('tofu-croustillant-brocoli', 2, 'Éponger le tofu avec un torchon, puis le rouler dans la fécule.'),
  ('tofu-croustillant-brocoli', 3, 'Chauffer l''huile de tournesol dans une grande poêle à feu moyen-vif et dorer le tofu 10 minutes en le retournant, jusqu''à ce qu''il soit croustillant sur toutes les faces.'),
  ('tofu-croustillant-brocoli', 4, 'Ajouter le brocoli, l''ail et le gingembre et faire sauter 5 minutes, jusqu''à ce que le brocoli soit tendre mais encore croquant.'),
  ('tofu-croustillant-brocoli', 5, 'Ajouter la sauce soja et l''huile de sésame, mélanger 30 secondes et parsemer de graines de sésame. Servir avec le riz.'),
  ('tortilla-espagnole', 1, 'Éplucher les pommes de terre et les couper en fines tranches ; émincer l''oignon.'),
  ('tortilla-espagnole', 2, 'Chauffer l''huile dans une poêle à feu doux. Ajouter les pommes de terre et l''oignon et les cuire 20 minutes en remuant de temps en temps : ils doivent être tendres mais pas dorés.'),
  ('tortilla-espagnole', 3, 'Battre les œufs avec le sel dans un saladier. Égoutter les pommes de terre et l''oignon en gardant un peu d''huile, puis les mélanger aux œufs.'),
  ('tortilla-espagnole', 4, 'Remettre un filet de l''huile dans la poêle à feu doux, verser le mélange et cuire 8 minutes, jusqu''à ce que les bords soient pris.'),
  ('tortilla-espagnole', 5, 'Poser une grande assiette sur la poêle, retourner la tortilla dessus, puis la faire glisser à nouveau dans la poêle. Cuire encore 5 minutes et servir tiède avec la salade.'),
  ('veloute-brocoli', 1, 'Émincer l''oignon ; détailler le brocoli en bouquets et éplucher la pomme de terre et la couper en dés.'),
  ('veloute-brocoli', 2, 'Dans un faitout à feu moyen, faire revenir l''oignon 3 minutes avec un filet d''eau.'),
  ('veloute-brocoli', 3, 'Ajouter le brocoli, la pomme de terre, l''eau et le cube émietté. Porter à ébullition puis cuire 20 minutes à frémissement, jusqu''à ce que les légumes soient tendres.'),
  ('veloute-brocoli', 4, 'Mixer avec la crème et l''emmental jusqu''à obtenir un velouté lisse. Saler et servir chaud.'),
  ('veloute-carottes-cumin', 1, 'Éplucher l''oignon et l''émincer ; éplucher les carottes et la pomme de terre et les couper en rondelles.'),
  ('veloute-carottes-cumin', 2, 'Dans un faitout à feu moyen, faire suer l''oignon 3 minutes avec un filet d''eau, puis ajouter le cumin 1 minute.'),
  ('veloute-carottes-cumin', 3, 'Ajouter les carottes, la pomme de terre, le cube émietté et l''eau. Porter à ébullition puis cuire 25 minutes à frémissement, jusqu''à ce que les carottes s''écrasent à la fourchette.'),
  ('veloute-carottes-cumin', 4, 'Mixer jusqu''à obtenir un velouté lisse et servir avec une cuillère de crème.'),
  ('veloute-champignons', 1, 'Émincer l''oignon et les champignons ; éplucher la pomme de terre et la couper en dés.'),
  ('veloute-champignons', 2, 'Faire fondre le beurre dans un faitout à feu moyen et faire revenir l''oignon et les champignons 8 minutes, jusqu''à ce qu''ils aient rendu leur eau.'),
  ('veloute-champignons', 3, 'Ajouter la pomme de terre, l''eau et le cube émietté. Porter à ébullition puis cuire 15 minutes à frémissement.'),
  ('veloute-champignons', 4, 'Mixer avec la crème jusqu''à obtenir un velouté lisse. Saler et parsemer de persil ciselé.'),
  ('veloute-poireaux-pommes-de-terre', 1, 'Émincer les poireaux et bien les rincer ; émincer l''oignon ; éplucher les pommes de terre et les couper en dés.'),
  ('veloute-poireaux-pommes-de-terre', 2, 'Faire fondre le beurre dans un faitout à feu moyen et faire fondre les poireaux et l''oignon 5 minutes, sans coloration.'),
  ('veloute-poireaux-pommes-de-terre', 3, 'Ajouter les pommes de terre, l''eau et le cube émietté. Porter à ébullition puis cuire 20 minutes à frémissement, jusqu''à ce que les pommes de terre soient tendres.'),
  ('veloute-poireaux-pommes-de-terre', 4, 'Mixer jusqu''à obtenir un velouté lisse, ajouter la crème, saler et servir chaud.'),
  ('wraps-thon-crudites', 1, 'Égoutter le thon et le maïs. Dans un bol, mélanger le thon avec la mayonnaise, le maïs et un peu de jus de citron.'),
  ('wraps-thon-crudites', 2, 'Laver et essorer la salade ; couper les tomates en fines rondelles.'),
  ('wraps-thon-crudites', 3, 'Poser chaque tortilla à plat, la garnir de salade, de tomate et du mélange au thon, en laissant un bord libre.'),
  ('wraps-thon-crudites', 4, 'Replier les côtés puis rouler serré en partant du bas. Couper en deux en biais et servir.'),
  ('yaourt-granola-fruits', 1, 'Répartir les yaourts dans deux bols.'),
  ('yaourt-granola-fruits', 2, 'Éplucher la banane et la couper en rondelles ; laver, équeuter et couper les fraises en quartiers.'),
  ('yaourt-granola-fruits', 3, 'Ajouter les flocons d''avoine et les fruits sur les yaourts.'),
  ('yaourt-granola-fruits', 4, 'Terminer avec un filet de miel et les amandes concassées.');
insert into public.recipe_steps (recipe_id, position, instruction)
