-- 0024 — Étapes des recettes réécrites, plus précises : feu (doux, moyen, vif), ustensile,
-- temps de cuisson et repère visuel (« jusqu'à ce que… ») à chaque étape de cuisson.
-- Contenu uniquement : mêmes recettes, mêmes ingrédients, mêmes quantités (aucune quantité
-- dans le texte, puisque les portions s'ajustent). Le matériel déduit des étapes est
-- recalculé automatiquement par le déclencheur recipe_steps_equipment.

-- Correctif de la règle du faitout (0023) : « faitout » en un mot n'était pas reconnu.
create or replace function public._recipe_equipment_compute(p_recipe_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_tags text[];
  v_text text;
  v_oven boolean;
begin
  select r.tags into v_tags from public.recipes r where r.id = p_recipe_id;
  if not found then
    return;
  end if;
  select coalesce(string_agg(s.instruction, ' '), '') into v_text
  from public.recipe_steps s where s.recipe_id = p_recipe_id;
  v_oven := 'four' = any(v_tags) or v_text ~* '(\mfour\M|°\s?C|enfourn)';

  delete from public.recipe_equipment where recipe_id = p_recipe_id;
  select p_recipe_id, code from (
    select 'four' as code where v_oven
    union all
    select 'plaques'
    where 'poele' = any(v_tags) or 'mijote' = any(v_tags)
       or v_text ~* '(po[êe]le|casserole|cocotte|sauteuse|\mwok|faire (revenir|cuire|fondre|bouillir|dorer|sauter)|[ée]bullition|bain-marie|mijot|saisi|\mfrire|blanchir|\mcuire\M)'
    union all
    select 'poele' where v_text ~* '(po[êe]le|sauteuse|\mwok\M)'
    union all
    select 'casserole'
    where v_text ~* '(casserole|eau bouillante|[ée]bullition|faire bouillir|b[ée]chamel|(cuire|cuisson)\s+(les|des|du|la)\s+(p[âa]tes|spaghetti|tagliatelles|penne|macaronis|coquillettes|nouilles|riz|quinoa|lentilles|pois chiches|pommes de terre))'
    union all
    select 'faitout' where v_text ~* '(faitout|fait-tout|cocotte|marmite)'
    union all
    select 'plat_four'
    where v_oven and v_text ~* '\m(dans un|dans le|un grand|le|un) plat\M'
    union all
    select 'moule' where v_text ~* '\m(dans|sur) (un|le) moule\M'
    union all
    select 'mixeur' where v_text ~* '\mmix(er|ez|é|ée|eur)'
    union all
    select 'micro_ondes' where v_text ~* 'micro-?ondes'
  ) t;
end;
$$;
revoke execute on function public._recipe_equipment_compute(uuid) from public, anon, authenticated;

create temporary table _new_steps (slug text not null, position smallint not null, instruction text not null);


do $$
declare
  v_missing text;
begin
  select string_agg(distinct n.slug, ', ') into v_missing
  from _new_steps n where not exists (select 1 from public.recipes r where r.slug = n.slug);
  if v_missing is not null then
    raise exception 'Recettes introuvables : %', v_missing;
  end if;
end;
$$;

delete from public.recipe_steps s
using public.recipes r
where s.recipe_id = r.id and r.slug in (select distinct slug from _new_steps);

select r.id, n.position, n.instruction
from _new_steps n join public.recipes r on r.slug = n.slug;

drop table _new_steps;
